window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ECC"]={"book":"ECC","editions":{"hbo-source":[[1,1,"דִּבְרֵי֙ קֹהֶ֣לֶת בֶּן־דָּוִ֔ד מֶ֖לֶךְ בִּ⁠ירוּשָׁלִָֽם׃","di̇bĕréy֙ qòhe֣leţ bėn-dá̇wi֔d me֖lekĕ bi̇⁠yrẇşá̌liáֽm׃"],[1,2,"הֲבֵ֤ל הֲבָלִים֙ אָמַ֣ר קֹהֶ֔לֶת הֲבֵ֥ל הֲבָלִ֖ים הַ⁠כֹּ֥ל הָֽבֶל׃","hàbé֤l hàbáliym֙ ʼáma֣r qòhe֔leţ hàbé֥l hàbáli֖ym ha⁠kò֥̇l háֽbel׃"],[1,3,"מַה־יִּתְר֖וֹן לָֽ⁠אָדָ֑ם בְּ⁠כָל־עֲמָל֔⁠וֹ שֶֽׁ⁠יַּעֲמֹ֖ל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","mah-yi̇ţĕr֖wòn láֽ⁠ʼádá֑m bĕ̇⁠kál-ʻàmál֔⁠wò şěֽ⁠yȧʻàmò֖l ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[1,4,"דּ֤וֹר הֹלֵךְ֙ וְ⁠ד֣וֹר בָּ֔א וְ⁠הָ⁠אָ֖רֶץ לְ⁠עוֹלָ֥ם עֹמָֽדֶת׃","ḋ֤wòr hòlékĕ֙ wĕ⁠d֣wòr bá̇֔ʼ wĕ⁠há⁠ʼá֖reẕ lĕ⁠ʻwòlá֥m ʻòmáֽdeţ׃"],[1,5,"וְ⁠זָרַ֥ח הַ⁠שֶּׁ֖מֶשׁ וּ⁠בָ֣א הַ⁠שָּׁ֑מֶשׁ וְ⁠אֶ֨ל־מְקוֹמ֔⁠וֹ שׁוֹאֵ֛ף זוֹרֵ֥חַֽ ה֖וּא שָֽׁם׃","wĕ⁠zára֥ẖ ha⁠şė֖̌meş̌ ẇ⁠bá֣ʼ ha⁠şá֑̇̌meş̌ wĕ⁠ʼe֨l-mĕqwòm֔⁠wò ş̌wòʼé֛p zwòré֥ẖaֽ h֖ẇʼ şáֽ̌m׃"],[1,6,"הוֹלֵךְ֙ אֶל־דָּר֔וֹם וְ⁠סוֹבֵ֖ב אֶל־צָפ֑וֹן סוֹבֵ֤ב ׀ סֹבֵב֙ הוֹלֵ֣ךְ הָ⁠ר֔וּחַ וְ⁠עַל־סְבִיבֹתָ֖י⁠ו שָׁ֥ב הָ⁠רֽוּחַ׃","hwòlékĕ֙ ʼel-dá̇r֔wòm wĕ⁠swòbé֖b ʼel-ẕáp֑wòn swòbé֤b ׀ sòbéb֙ hwòlé֣kĕ há⁠r֔ẇẖa wĕ⁠ʻal-sĕbiybòţá֖y⁠w şá֥̌b há⁠rֽẇẖa׃"],[1,7,"כָּל־הַ⁠נְּחָלִים֙ הֹלְכִ֣ים אֶל־הַ⁠יָּ֔ם וְ⁠הַ⁠יָּ֖ם אֵינֶ֣⁠נּוּ מָלֵ֑א אֶל־מְק֗וֹם שֶׁ֤⁠הַ⁠נְּחָלִים֙ הֹֽלְכִ֔ים שָׁ֛ם הֵ֥ם שָׁבִ֖ים לָ⁠לָֽכֶת׃","ká̇l-ha⁠nĕ̇ẖáliym֙ hòlĕki֣ym ʼel-ha⁠yá̇֔m wĕ⁠ha⁠yá֖̇m ʼéyne֣⁠ṅẇ málé֑ʼ ʼel-mĕq֗wòm şě֤⁠ha⁠nĕ̇ẖáliym֙ hòֽlĕki֔ym şá֛̌m hé֥m şá̌bi֖ym lá⁠láֽkeţ׃"],[1,8,"כָּל־הַ⁠דְּבָרִ֣ים יְגֵעִ֔ים לֹא־יוּכַ֥ל אִ֖ישׁ לְ⁠דַבֵּ֑ר לֹא־תִשְׂבַּ֥ע עַ֨יִן֙ לִ⁠רְא֔וֹת וְ⁠לֹא־תִמָּלֵ֥א אֹ֖זֶן מִ⁠שְּׁמֹֽעַ׃","ká̇l-ha⁠dĕ̇bári֣ym yĕgéʻi֔ym lòʼ-yẇka֥l ʼi֖yş̌ lĕ⁠dabé֑̇r lòʼ-ţişĕ̂bȧ֥ʻ ʻa֨yin֙ li⁠rĕʼ֔wòţ wĕ⁠lòʼ-ţimá̇lé֥ʼ ʼò֖zen mi⁠şĕ̇̌mòֽʻa׃"],[1,9,"מַה־שֶּֽׁ⁠הָיָה֙ ה֣וּא שֶׁ⁠יִּהְיֶ֔ה וּ⁠מַה־שֶׁ⁠נַּֽעֲשָׂ֔ה ה֖וּא שֶׁ⁠יֵּעָשֶׂ֑ה וְ⁠אֵ֥ין כָּל־חָדָ֖שׁ תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","mah-şėֽ̌⁠háyáh֙ h֣ẇʼ şě⁠yi̇hĕye֔h ẇ⁠mah-şě⁠nȧֽʻàşá̂֔h h֖ẇʼ şě⁠yé̇ʻáşê֑h wĕ⁠ʼé֥yn ká̇l-ẖádá֖ş̌ ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[1,10,"יֵ֥שׁ דָּבָ֛ר שֶׁ⁠יֹּאמַ֥ר רְאֵה־זֶ֖ה חָדָ֣שׁ ה֑וּא כְּבָר֙ הָיָ֣ה לְ⁠עֹֽלָמִ֔ים אֲשֶׁ֥ר הָיָ֖ה מִ⁠לְּ⁠פָנֵֽ⁠נוּ׃","yé֥ş̌ dá̇bá֛r şě⁠yò̇ʼma֥r rĕʼéh-ze֖h ẖádá֣ş̌ h֑ẇʼ kĕ̇bár֙ háyá֣h lĕ⁠ʻòֽlámi֔ym ʼàşě֥r háyá֖h mi⁠lĕ̇⁠pánéֽ⁠nẇ׃"],[1,11,"אֵ֥ין זִכְר֖וֹן לָ⁠רִאשֹׁנִ֑ים וְ⁠גַ֨ם לָ⁠אַחֲרֹנִ֜ים שֶׁ⁠יִּהְי֗וּ לֹֽא־יִהְיֶ֤ה לָ⁠הֶם֙ זִכָּר֔וֹן עִ֥ם שֶׁ⁠יִּהְי֖וּ לָ⁠אַחֲרֹנָֽה׃פ","ʼé֥yn zikĕr֖wòn lá⁠riʼşò̌ni֑ym wĕ⁠ga֨m lá⁠ʼaẖàròni֜ym şě⁠yi̇hĕy֗ẇ lòֽʼ-yihĕye֤h lá⁠hem֙ ziká̇r֔wòn ʻi֥m şě⁠yi̇hĕy֖ẇ lá⁠ʼaẖàrònáֽh׃p"],[1,12,"אֲנִ֣י קֹהֶ֗לֶת הָיִ֥יתִי מֶ֛לֶךְ עַל־יִשְׂרָאֵ֖ל בִּ⁠ירוּשָׁלִָֽם׃","ʼàni֣y qòhe֗leţ háyi֥yţiy me֛lekĕ ʻal-yişĕ̂ráʼé֖l bi̇⁠yrẇşá̌liáֽm׃"],[1,13,"וְ⁠נָתַ֣תִּי אֶת־לִבִּ֗⁠י לִ⁠דְר֤וֹשׁ וְ⁠לָ⁠תוּר֙ בַּֽ⁠חָכְמָ֔ה עַ֛ל כָּל־אֲשֶׁ֥ר נַעֲשָׂ֖ה תַּ֣חַת הַ⁠שָּׁמָ֑יִם ה֣וּא ׀ עִנְיַ֣ן רָ֗ע נָתַ֧ן אֱלֹהִ֛ים לִ⁠בְנֵ֥י הָ⁠אָדָ֖ם לַ⁠עֲנ֥וֹת בּֽ⁠וֹ׃","wĕ⁠náţa֣ţi̇y ʼeţ-libi̇֗⁠y li⁠dĕr֤wòş̌ wĕ⁠lá⁠ţẇr֙ bȧֽ⁠ẖákĕmá֔h ʻa֛l ká̇l-ʼàşě֥r naʻàşá֖̂h ţȧ֣ẖaţ ha⁠şá̇̌má֑yim h֣ẇʼ ׀ ʻinĕya֣n rá֗ʻ náţa֧n ʼèlòhi֛ym li⁠bĕné֥y há⁠ʼádá֖m la⁠ʻàn֥wòţ ḃֽ⁠wò׃"],[1,14,"רָאִ֨יתִי֙ אֶת־כָּל־הַֽ⁠מַּעֲשִׂ֔ים שֶֽׁ⁠נַּעֲשׂ֖וּ תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וְ⁠הִנֵּ֥ה הַ⁠כֹּ֛ל הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","ráʼi֨yţiy֙ ʼeţ-ká̇l-haֽ⁠mȧʻàşî֔ym şěֽ⁠nȧʻàş֖̂ẇ ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ wĕ⁠hiné֥̇h ha⁠kò֛̇l he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[1,15,"מְעֻוָּ֖ת לֹא־יוּכַ֣ל לִ⁠תְקֹ֑ן וְ⁠חֶסְר֖וֹן לֹא־יוּכַ֥ל לְ⁠הִמָּנֽוֹת׃","mĕʻuwá֖̇ţ lòʼ-yẇka֣l li⁠ţĕqò֑n wĕ⁠ẖesĕr֖wòn lòʼ-yẇka֥l lĕ⁠himá̇nֽwòţ׃"],[1,16,"דִּבַּ֨רְתִּי אֲנִ֤י עִם־לִבִּ⁠י֙ לֵ⁠אמֹ֔ר אֲנִ֗י הִנֵּ֨ה הִגְדַּ֤לְתִּי וְ⁠הוֹסַ֨פְתִּי֙ חָכְמָ֔ה עַ֛ל כָּל־אֲשֶׁר־הָיָ֥ה לְ⁠פָנַ֖⁠י עַל־יְרוּשָׁלִָ֑ם וְ⁠לִבִּ֛⁠י רָאָ֥ה הַרְבֵּ֖ה חָכְמָ֥ה וָ⁠דָֽעַת׃","di̇bȧ֨rĕţi̇y ʼàni֤y ʻim-libi̇⁠y֙ lé⁠ʼmò֔r ʼàni֗y hiné̇֨h higĕdȧ֤lĕţi̇y wĕ⁠hwòsa֨pĕţi̇y֙ ẖákĕmá֔h ʻa֛l ká̇l-ʼàşěr-háyá֥h lĕ⁠pána֖⁠y ʻal-yĕrẇşá̌liá֑m wĕ⁠libi֛̇⁠y ráʼá֥h harĕbé֖̇h ẖákĕmá֥h wá⁠dáֽʻaţ׃"],[1,17,"וָ⁠אֶתְּנָ֤⁠ה לִבִּ⁠י֙ לָ⁠דַ֣עַת חָכְמָ֔ה וְ⁠דַ֥עַת הוֹלֵל֖וֹת וְ⁠שִׂכְל֑וּת יָדַ֕עְתִּי שֶׁ⁠גַּם־זֶ֥ה ה֖וּא רַעְי֥וֹן רֽוּחַ׃","wá⁠ʼeţĕ̇ná֤⁠h libi̇⁠y֙ lá⁠da֣ʻaţ ẖákĕmá֔h wĕ⁠da֥ʻaţ hwòlél֖wòţ wĕ⁠şîkĕl֑ẇţ yáda֕ʻĕţi̇y şě⁠gȧm-ze֥h h֖ẇʼ raʻĕy֥wòn rֽẇẖa׃"],[1,18,"כִּ֛י בְּ⁠רֹ֥ב חָכְמָ֖ה רָב־כָּ֑עַס וְ⁠יוֹסִ֥יף דַּ֖עַת יוֹסִ֥יף מַכְאֽוֹב׃","ki֛̇y bĕ̇⁠rò֥b ẖákĕmá֖h ráb-ká֑̇ʻas wĕ⁠ywòsi֥yp dȧ֖ʻaţ ywòsi֥yp makĕʼֽwòb׃"],[2,1,"אָמַ֤רְתִּֽי אֲנִי֙ בְּ⁠לִבִּ֔⁠י לְכָ⁠ה־נָּ֛א אֲנַסְּ⁠כָ֛ה בְ⁠שִׂמְחָ֖ה וּ⁠רְאֵ֣ה בְ⁠ט֑וֹב וְ⁠הִנֵּ֥ה גַם־ה֖וּא הָֽבֶל׃","ʼáma֤rĕţiֽ̇y ʼàniy֙ bĕ̇⁠libi̇֔⁠y lĕká⁠h-ná֛̇ʼ ʼànasĕ̇⁠ká֛h bĕ⁠şîmĕẖá֖h ẇ⁠rĕʼé֣h bĕ⁠t֑wòb wĕ⁠hiné֥̇h gam-h֖ẇʼ háֽbel׃"],[2,2,"לִ⁠שְׂח֖וֹק אָמַ֣רְתִּי מְהוֹלָ֑ל וּ⁠לְ⁠שִׂמְחָ֖ה מַה־זֹּ֥ה עֹשָֽׂה׃","li⁠şĕ̂ẖ֖wòq ʼáma֣rĕţi̇y mĕhwòlá֑l ẇ⁠lĕ⁠şîmĕẖá֖h mah-zò֥̇h ʻòşáֽ̂h׃"],[2,3,"תַּ֣רְתִּי בְ⁠לִבִּ֔⁠י לִ⁠מְשׁ֥וֹךְ בַּ⁠יַּ֖יִן אֶת־בְּשָׂרִ֑⁠י וְ⁠לִבִּ֞⁠י נֹהֵ֤ג בַּֽ⁠חָכְמָה֙ וְ⁠לֶ⁠אֱחֹ֣ז בְּ⁠סִכְל֔וּת עַ֣ד אֲשֶׁר־אֶרְאֶ֗ה אֵי־זֶ֨ה ט֜וֹב לִ⁠בְנֵ֤י הָ⁠אָדָם֙ אֲשֶׁ֤ר יַעֲשׂוּ֙ תַּ֣חַת הַ⁠שָּׁמַ֔יִם מִסְפַּ֖ר יְמֵ֥י חַיֵּי⁠הֶֽם׃","ţȧ֣rĕţi̇y bĕ⁠libi̇֔⁠y li⁠mĕş֥̌wòkĕ bȧ⁠yȧ֖yin ʼeţ-bĕ̇şá̂ri֑⁠y wĕ⁠libi̇֞⁠y nòhé֤g bȧֽ⁠ẖákĕmáh֙ wĕ⁠le⁠ʼèẖò֣z bĕ̇⁠sikĕl֔ẇţ ʻa֣d ʼàşěr-ʼerĕʼe֗h ʼéy-ze֨h t֜wòb li⁠bĕné֤y há⁠ʼádám֙ ʼàşě֤r yaʻàş̂ẇ֙ ţȧ֣ẖaţ ha⁠şá̇̌ma֔yim misĕpȧ֖r yĕmé֥y ẖayé̇y⁠heֽm׃"],[2,4,"הִגְדַּ֖לְתִּי מַעֲשָׂ֑⁠י בָּנִ֤יתִי לִ⁠י֙ בָּתִּ֔ים נָטַ֥עְתִּי לִ֖⁠י כְּרָמִֽים׃","higĕdȧ֖lĕţi̇y maʻàşá֑̂⁠y bá̇ni֤yţiy li⁠y֙ bá̇ţi̇֔ym náta֥ʻĕţi̇y li֖⁠y kĕ̇rámiֽym׃"],[2,5,"עָשִׂ֣יתִי לִ֔⁠י גַּנּ֖וֹת וּ⁠פַרְדֵּסִ֑ים וְ⁠נָטַ֥עְתִּי בָ⁠הֶ֖ם עֵ֥ץ כָּל־פֶּֽרִי׃","ʻáşî֣yţiy li֔⁠y gȧṅ֖wòţ ẇ⁠parĕdé̇si֑ym wĕ⁠náta֥ʻĕţi̇y bá⁠he֖m ʻé֥ẕ ká̇l-pėֽriy׃"],[2,6,"עָשִׂ֥יתִי לִ֖⁠י בְּרֵכ֣וֹת מָ֑יִם לְ⁠הַשְׁק֣וֹת מֵ⁠הֶ֔ם יַ֖עַר צוֹמֵ֥חַ עֵצִֽים׃","ʻáşî֥yţiy li֖⁠y bĕ̇rék֣wòţ má֑yim lĕ⁠haşĕ̌q֣wòţ mé⁠he֔m ya֖ʻar ẕwòmé֥ẖa ʻéẕiֽym׃"],[2,7,"קָנִ֨יתִי֙ עֲבָדִ֣ים וּ⁠שְׁפָח֔וֹת וּ⁠בְנֵי־בַ֖יִת הָ֣יָה לִ֑⁠י גַּ֣ם מִקְנֶה֩ בָקָ֨ר וָ⁠צֹ֤אן הַרְבֵּה֙ הָ֣יָה לִ֔⁠י מִ⁠כֹּ֛ל שֶֽׁ⁠הָי֥וּ לְ⁠פָנַ֖⁠י בִּ⁠ירוּשָׁלִָֽם׃","qáni֨yţiy֙ ʻàbádi֣ym ẇ⁠şĕ̌páẖ֔wòţ ẇ⁠bĕnéy-ba֖yiţ há֣yáh li֑⁠y gȧ֣m miqĕneh֩ báqá֨r wá⁠ẕò֤ʼn harĕbé̇h֙ há֣yáh li֔⁠y mi⁠kò֛̇l şěֽ⁠háy֥ẇ lĕ⁠pána֖⁠y bi̇⁠yrẇşá̌liáֽm׃"],[2,8,"כָּנַ֤סְתִּי לִ⁠י֙ גַּם־כֶּ֣סֶף וְ⁠זָהָ֔ב וּ⁠סְגֻלַּ֥ת מְלָכִ֖ים וְ⁠הַ⁠מְּדִינ֑וֹת עָשִׂ֨יתִי לִ֜⁠י שָׁרִ֣ים וְ⁠שָׁר֗וֹת וְ⁠תַעֲנוּגֹ֛ת בְּנֵ֥י הָ⁠אָדָ֖ם שִׁדָּ֥ה וְ⁠שִׁדּֽוֹת׃","ká̇na֤sĕţi̇y li⁠y֙ gȧm-kė֣sep wĕ⁠záhá֔b ẇ⁠sĕgulȧ֥ţ mĕláki֖ym wĕ⁠ha⁠mĕ̇diyn֑wòţ ʻáşî֨yţiy li֜⁠y şá̌ri֣ym wĕ⁠şá̌r֗wòţ wĕ⁠ţaʻànẇgò֛ţ bĕ̇né֥y há⁠ʼádá֖m şǐdá֥̇h wĕ⁠şǐḋֽwòţ׃"],[2,9,"וְ⁠גָדַ֣לְתִּי וְ⁠הוֹסַ֔פְתִּי מִ⁠כֹּ֛ל שֶׁ⁠הָיָ֥ה לְ⁠פָנַ֖⁠י בִּ⁠ירוּשָׁלִָ֑ם אַ֥ף חָכְמָתִ֖⁠י עָ֥מְדָה לִּֽ⁠י׃","wĕ⁠gáda֣lĕţi̇y wĕ⁠hwòsa֔pĕţi̇y mi⁠kò֛̇l şě⁠háyá֥h lĕ⁠pána֖⁠y bi̇⁠yrẇşá̌liá֑m ʼa֥p ẖákĕmáţi֖⁠y ʻá֥mĕdáh liֽ̇⁠y׃"],[2,10,"וְ⁠כֹל֙ אֲשֶׁ֣ר שָֽׁאֲל֣וּ עֵינַ֔⁠י לֹ֥א אָצַ֖לְתִּי מֵ⁠הֶ֑ם לֹֽא־מָנַ֨עְתִּי אֶת־לִבִּ֜⁠י מִ⁠כָּל־שִׂמְחָ֗ה כִּֽי־לִבִּ֤⁠י שָׂמֵ֨חַ֙ מִ⁠כָּל־עֲמָלִ֔⁠י וְ⁠זֶֽה־הָיָ֥ה חֶלְקִ֖⁠י מִ⁠כָּל־עֲמָלִֽ⁠י׃","wĕ⁠kòl֙ ʼàşě֣r şáֽ̌ʼàl֣ẇ ʻéyna֔⁠y lò֥ʼ ʼáẕa֖lĕţi̇y mé⁠he֑m lòֽʼ-mána֨ʻĕţi̇y ʼeţ-libi̇֜⁠y mi⁠ká̇l-şîmĕẖá֗h kiֽ̇y-libi֤̇⁠y şá̂mé֨ẖa֙ mi⁠ká̇l-ʻàmáli֔⁠y wĕ⁠zeֽh-háyá֥h ẖelĕqi֖⁠y mi⁠ká̇l-ʻàmáliֽ⁠y׃"],[2,11,"וּ⁠פָנִ֣יתִֽי אֲנִ֗י בְּ⁠כָל־מַעֲשַׂ⁠י֙ שֶֽׁ⁠עָשׂ֣וּ יָדַ֔⁠י וּ⁠בֶֽ⁠עָמָ֖ל שֶׁ⁠עָמַ֣לְתִּי לַ⁠עֲשׂ֑וֹת וְ⁠הִנֵּ֨ה הַ⁠כֹּ֥ל הֶ֨בֶל֙ וּ⁠רְע֣וּת ר֔וּחַ וְ⁠אֵ֥ין יִתְר֖וֹן תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","ẇ⁠páni֣yţiֽy ʼàni֗y bĕ̇⁠kál-maʻàşâ⁠y֙ şěֽ⁠ʻáş֣̂ẇ yáda֔⁠y ẇ⁠beֽ⁠ʻámá֖l şě⁠ʻáma֣lĕţi̇y la⁠ʻàş֑̂wòţ wĕ⁠hiné̇֨h ha⁠kò֥̇l he֨bel֙ ẇ⁠rĕʻ֣ẇţ r֔ẇẖa wĕ⁠ʼé֥yn yiţĕr֖wòn ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[2,12,"וּ⁠פָנִ֤יתִֽי אֲנִי֙ לִ⁠רְא֣וֹת חָכְמָ֔ה וְ⁠הוֹלֵל֖וֹת וְ⁠סִכְל֑וּת כִּ֣י ׀ מֶ֣ה הָ⁠אָדָ֗ם שֶׁ⁠יָּבוֹא֙ אַחֲרֵ֣י הַ⁠מֶּ֔לֶךְ אֵ֥ת אֲשֶׁר־כְּבָ֖ר עָשֽׂוּ⁠הוּ׃","ẇ⁠páni֤yţiֽy ʼàniy֙ li⁠rĕʼ֣wòţ ẖákĕmá֔h wĕ⁠hwòlél֖wòţ wĕ⁠sikĕl֑ẇţ ki֣̇y ׀ me֣h há⁠ʼádá֗m şě⁠yá̇bwòʼ֙ ʼaẖàré֣y ha⁠mė֔lekĕ ʼé֥ţ ʼàşěr-kĕ̇bá֖r ʻáşֽ̂ẇ⁠hẇ׃"],[2,13,"וְ⁠רָאִ֣יתִי אָ֔נִי שֶׁ⁠יֵּ֥שׁ יִתְר֛וֹן לַֽ⁠חָכְמָ֖ה מִן־הַ⁠סִּכְל֑וּת כִּֽ⁠יתְר֥וֹן הָ⁠א֖וֹר מִן־הַ⁠חֹֽשֶׁךְ׃","wĕ⁠ráʼi֣yţiy ʼá֔niy şě⁠yé֥̇ş̌ yiţĕr֛wòn laֽ⁠ẖákĕmá֖h min-ha⁠si̇kĕl֑ẇţ kiֽ̇⁠yţĕr֥wòn há⁠ʼ֖wòr min-ha⁠ẖòֽşěkĕ׃"],[2,14,"הֶֽ⁠חָכָם֙ עֵינָ֣י⁠ו בְּ⁠רֹאשׁ֔⁠וֹ וְ⁠הַ⁠כְּסִ֖יל בַּ⁠חֹ֣שֶׁךְ הוֹלֵ֑ךְ וְ⁠יָדַ֣עְתִּי גַם־אָ֔נִי שֶׁ⁠מִּקְרֶ֥ה אֶחָ֖ד יִקְרֶ֥ה אֶת־כֻּלָּֽ⁠ם׃","heֽ⁠ẖákám֙ ʻéyná֣y⁠w bĕ̇⁠ròʼş̌֔⁠wò wĕ⁠ha⁠kĕ̇si֖yl bȧ⁠ẖò֣şěkĕ hwòlé֑kĕ wĕ⁠yáda֣ʻĕţi̇y gam-ʼá֔niy şě⁠mi̇qĕre֥h ʼeẖá֖d yiqĕre֥h ʼeţ-ku̇láֽ̇⁠m׃"],[2,15,"וְ⁠אָמַ֨רְתִּֽי אֲנִ֜י בְּ⁠לִבִּ֗⁠י כְּ⁠מִקְרֵ֤ה הַ⁠כְּסִיל֙ גַּם־אֲנִ֣י יִקְרֵ֔⁠נִי וְ⁠לָ֧⁠מָּה חָכַ֛מְתִּי אֲנִ֖י אָ֣ז יוֹתֵ֑ר וְ⁠דִבַּ֣רְתִּי בְ⁠לִבִּ֔⁠י שֶׁ⁠גַּם־זֶ֖ה הָֽבֶל׃","wĕ⁠ʼáma֨rĕţiֽ̇y ʼàni֜y bĕ̇⁠libi̇֗⁠y kĕ̇⁠miqĕré֤h ha⁠kĕ̇siyl֙ gȧm-ʼàni֣y yiqĕré֔⁠niy wĕ⁠lá֧⁠má̇h ẖáka֛mĕţi̇y ʼàni֖y ʼá֣z ywòţé֑r wĕ⁠dibȧ֣rĕţi̇y bĕ⁠libi̇֔⁠y şě⁠gȧm-ze֖h háֽbel׃"],[2,16,"כִּי֩ אֵ֨ין זִכְר֧וֹן לֶ⁠חָכָ֛ם עִֽם־הַ⁠כְּסִ֖יל לְ⁠עוֹלָ֑ם בְּ⁠שֶׁ⁠כְּבָ֞ר הַ⁠יָּמִ֤ים הַ⁠בָּאִים֙ הַ⁠כֹּ֣ל נִשְׁכָּ֔ח וְ⁠אֵ֛יךְ יָמ֥וּת הֶ⁠חָכָ֖ם עִֽם־הַ⁠כְּסִֽיל׃","ki̇y֩ ʼé֨yn zikĕr֧wòn le⁠ẖáká֛m ʻiֽm-ha⁠kĕ̇si֖yl lĕ⁠ʻwòlá֑m bĕ̇⁠şě⁠kĕ̇bá֞r ha⁠yá̇mi֤ym ha⁠bá̇ʼiym֙ ha⁠kò֣̇l nişĕ̌ká̇֔ẖ wĕ⁠ʼé֛ykĕ yám֥ẇţ he⁠ẖáká֖m ʻiֽm-ha⁠kĕ̇siֽyl׃"],[2,17,"וְ⁠שָׂנֵ֨אתִי֙ אֶת־הַ֣⁠חַיִּ֔ים כִּ֣י רַ֤ע עָלַ⁠י֙ הַֽ⁠מַּעֲשֶׂ֔ה שֶׁ⁠נַּעֲשָׂ֖ה תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ כִּֽי־הַ⁠כֹּ֥ל הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","wĕ⁠şá̂né֨ʼţiy֙ ʼeţ-ha֣⁠ẖayi̇֔ym ki֣̇y ra֤ʻ ʻála⁠y֙ haֽ⁠mȧʻàşê֔h şě⁠nȧʻàşá֖̂h ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ kiֽ̇y-ha⁠kò֥̇l he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[2,18,"וְ⁠שָׂנֵ֤אתִֽי אֲנִי֙ אֶת־כָּל־עֲמָלִ֔⁠י שֶׁ⁠אֲנִ֥י עָמֵ֖ל תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ שֶׁ֣⁠אַנִּיחֶ֔⁠נּוּ לָ⁠אָדָ֖ם שֶׁ⁠יִּהְיֶ֥ה אַחֲרָֽ⁠י׃","wĕ⁠şá̂né֤ʼţiֽy ʼàniy֙ ʼeţ-ká̇l-ʻàmáli֔⁠y şě⁠ʼàni֥y ʻámé֖l ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ şě֣⁠ʼani̇yẖe֔⁠ṅẇ lá⁠ʼádá֖m şě⁠yi̇hĕye֥h ʼaẖàráֽ⁠y׃"],[2,19,"וּ⁠מִ֣י יוֹדֵ֗עַ הֶֽ⁠חָכָ֤ם יִהְיֶה֙ א֣וֹ סָכָ֔ל וְ⁠יִשְׁלַט֙ בְּ⁠כָל־עֲמָלִ֔⁠י שֶֽׁ⁠עָמַ֥לְתִּי וְ⁠שֶׁ⁠חָכַ֖מְתִּי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ גַּם־זֶ֖ה הָֽבֶל׃","ẇ⁠mi֣y ywòdé֗ʻa heֽ⁠ẖáká֤m yihĕyeh֙ ʼ֣wò sáká֔l wĕ⁠yişĕ̌lat֙ bĕ̇⁠kál-ʻàmáli֔⁠y şěֽ⁠ʻáma֥lĕţi̇y wĕ⁠şě⁠ẖáka֖mĕţi̇y ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ gȧm-ze֖h háֽbel׃"],[2,20,"וְ⁠סַבּ֥וֹתִֽי אֲנִ֖י לְ⁠יַאֵ֣שׁ אֶת־לִבִּ֑⁠י עַ֚ל כָּל־הֶ֣⁠עָמָ֔ל שֶׁ⁠עָמַ֖לְתִּי תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠saḃ֥wòţiֽy ʼàni֖y lĕ⁠yaʼé֣ş̌ ʼeţ-libi֑̇⁠y ʻa֚l ká̇l-he֣⁠ʻámá֔l şě⁠ʻáma֖lĕţi̇y ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[2,21,"כִּי־יֵ֣שׁ אָדָ֗ם שֶׁ⁠עֲמָל֛⁠וֹ בְּ⁠חָכְמָ֥ה וּ⁠בְ⁠דַ֖עַת וּ⁠בְ⁠כִשְׁר֑וֹן וּ⁠לְ⁠אָדָ֞ם שֶׁ⁠לֹּ֤א עָֽמַל־בּ⁠וֹ֙ יִתְּנֶ֣⁠נּוּ חֶלְק֔⁠וֹ גַּם־זֶ֥ה הֶ֖בֶל וְ⁠רָעָ֥ה רַבָּֽה׃","ki̇y-yé֣ş̌ ʼádá֗m şě⁠ʻàmál֛⁠wò bĕ̇⁠ẖákĕmá֥h ẇ⁠bĕ⁠da֖ʻaţ ẇ⁠bĕ⁠kişĕ̌r֑wòn ẇ⁠lĕ⁠ʼádá֞m şě⁠lò֤̇ʼ ʻáֽmal-ḃ⁠wò֙ yiţĕ̇ne֣⁠ṅẇ ẖelĕq֔⁠wò gȧm-ze֥h he֖bel wĕ⁠ráʻá֥h rabáֽ̇h׃"],[2,22,"כִּ֠י מֶֽה־הֹוֶ֤ה לָֽ⁠אָדָם֙ בְּ⁠כָל־עֲמָל֔⁠וֹ וּ⁠בְ⁠רַעְי֖וֹן לִבּ֑⁠ו שֶׁ⁠ה֥וּא עָמֵ֖ל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","ki̇֠y meֽh-hòwe֤h láֽ⁠ʼádám֙ bĕ̇⁠kál-ʻàmál֔⁠wò ẇ⁠bĕ⁠raʻĕy֖wòn liḃ֑⁠w şě⁠h֥ẇʼ ʻámé֖l ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[2,23,"כִּ֧י כָל־יָמָ֣י⁠ו מַכְאֹבִ֗ים וָ⁠כַ֨עַס֙ עִנְיָנ֔⁠וֹ גַּם־בַּ⁠לַּ֖יְלָה לֹא־שָׁכַ֣ב לִבּ֑⁠וֹ גַּם־זֶ֖ה הֶ֥בֶל הֽוּא׃","ki֧̇y kál-yámá֣y⁠w makĕʼòbi֗ym wá⁠ka֨ʻas֙ ʻinĕyán֔⁠wò gȧm-bȧ⁠lȧ֖yĕláh lòʼ-şá̌ka֣b liḃ֑⁠wò gȧm-ze֖h he֥bel hֽẇʼ׃"],[2,24,"אֵֽין־ט֤וֹב בָּ⁠אָדָם֙ שֶׁ⁠יֹּאכַ֣ל וְ⁠שָׁתָ֔ה וְ⁠הֶרְאָ֧ה אֶת־נַפְשׁ֛⁠וֹ ט֖וֹב בַּ⁠עֲמָל֑⁠וֹ גַּם־זֹה֙ רָאִ֣יתִי אָ֔נִי כִּ֛י מִ⁠יַּ֥ד הָ⁠אֱלֹהִ֖ים הִֽיא׃","ʼéֽyn-t֤wòb bá̇⁠ʼádám֙ şě⁠yò̇ʼka֣l wĕ⁠şá̌ţá֔h wĕ⁠herĕʼá֧h ʼeţ-napĕş֛̌⁠wò t֖wòb bȧ⁠ʻàmál֑⁠wò gȧm-zòh֙ ráʼi֣yţiy ʼá֔niy ki֛̇y mi⁠yȧ֥d há⁠ʼèlòhi֖ym hiֽyʼ׃"],[2,25,"כִּ֣י מִ֥י יֹאכַ֛ל וּ⁠מִ֥י יָח֖וּשׁ ח֥וּץ מִמֶּֽ⁠נִּי׃","ki֣̇y mi֥y yòʼka֛l ẇ⁠mi֥y yáẖ֖ẇş̌ ẖ֥ẇẕ mimėֽ⁠ni̇y׃"],[2,26,"כִּ֤י לְ⁠אָדָם֙ שֶׁ⁠טּ֣וֹב לְ⁠פָנָ֔י⁠ו נָתַ֛ן חָכְמָ֥ה וְ⁠דַ֖עַת וְ⁠שִׂמְחָ֑ה וְ⁠לַ⁠חוֹטֶא֩ נָתַ֨ן עִנְיָ֜ן לֶ⁠אֱס֣וֹף וְ⁠לִ⁠כְנ֗וֹס לָ⁠תֵת֙ לְ⁠טוֹב֙ לִ⁠פְנֵ֣י הָֽ⁠אֱלֹהִ֔ים גַּם־זֶ֥ה הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","ki֤̇y lĕ⁠ʼádám֙ şě⁠ṫ֣wòb lĕ⁠páná֔y⁠w náţa֛n ẖákĕmá֥h wĕ⁠da֖ʻaţ wĕ⁠şîmĕẖá֑h wĕ⁠la⁠ẖwòteʼ֩ náţa֨n ʻinĕyá֜n le⁠ʼès֣wòp wĕ⁠li⁠kĕn֗wòs lá⁠ţéţ֙ lĕ⁠twòb֙ li⁠pĕné֣y háֽ⁠ʼèlòhi֔ym gȧm-ze֥h he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[3,1,"לַ⁠כֹּ֖ל זְמָ֑ן וְ⁠עֵ֥ת לְ⁠כָל־חֵ֖פֶץ תַּ֥חַת הַ⁠שָּׁמָֽיִם׃ס","la⁠kò֖̇l zĕmá֑n wĕ⁠ʻé֥ţ lĕ⁠kál-ẖé֖peẕ ţȧ֥ẖaţ ha⁠şá̇̌máֽyim׃s"],[3,2,"עֵ֥ת לָ⁠לֶ֖דֶת וְ⁠עֵ֣ת לָ⁠מ֑וּת עֵ֣ת לָ⁠טַ֔עַת וְ⁠עֵ֖ת לַ⁠עֲק֥וֹר נָטֽוּעַ׃","ʻé֥ţ lá⁠le֖deţ wĕ⁠ʻé֣ţ lá⁠m֑ẇţ ʻé֣ţ lá⁠ta֔ʻaţ wĕ⁠ʻé֖ţ la⁠ʻàq֥wòr nátֽẇʻa׃"],[3,3,"עֵ֤ת לַ⁠הֲרוֹג֙ וְ⁠עֵ֣ת לִ⁠רְפּ֔וֹא עֵ֥ת לִ⁠פְר֖וֹץ וְ⁠עֵ֥ת לִ⁠בְנֽוֹת׃","ʻé֤ţ la⁠hàrwòg֙ wĕ⁠ʻé֣ţ li⁠rĕṗ֔wòʼ ʻé֥ţ li⁠pĕr֖wòẕ wĕ⁠ʻé֥ţ li⁠bĕnֽwòţ׃"],[3,4,"עֵ֤ת לִ⁠בְכּוֹת֙ וְ⁠עֵ֣ת לִ⁠שְׂח֔וֹק עֵ֥ת סְפ֖וֹד וְ⁠עֵ֥ת רְקֽוֹד׃","ʻé֤ţ li⁠bĕk̇wòţ֙ wĕ⁠ʻé֣ţ li⁠şĕ̂ẖ֔wòq ʻé֥ţ sĕp֖wòd wĕ⁠ʻé֥ţ rĕqֽwòd׃"],[3,5,"עֵ֚ת לְ⁠הַשְׁלִ֣יךְ אֲבָנִ֔ים וְ⁠עֵ֖ת כְּנ֣וֹס אֲבָנִ֑ים עֵ֣ת לַ⁠חֲב֔וֹק וְ⁠עֵ֖ת לִ⁠רְחֹ֥ק מֵ⁠חַבֵּֽק׃","ʻé֚ţ lĕ⁠haşĕ̌li֣ykĕ ʼàbáni֔ym wĕ⁠ʻé֖ţ kĕ̇n֣wòs ʼàbáni֑ym ʻé֣ţ la⁠ẖàb֔wòq wĕ⁠ʻé֖ţ li⁠rĕẖò֥q mé⁠ẖabéֽ̇q׃"],[3,6,"עֵ֤ת לְ⁠בַקֵּשׁ֙ וְ⁠עֵ֣ת לְ⁠אַבֵּ֔ד עֵ֥ת לִ⁠שְׁמ֖וֹר וְ⁠עֵ֥ת לְ⁠הַשְׁלִֽיךְ׃","ʻé֤ţ lĕ⁠baqé̇ş̌֙ wĕ⁠ʻé֣ţ lĕ⁠ʼabé̇֔d ʻé֥ţ li⁠şĕ̌m֖wòr wĕ⁠ʻé֥ţ lĕ⁠haşĕ̌liֽykĕ׃"],[3,7,"עֵ֤ת לִ⁠קְר֨וֹעַ֙ וְ⁠עֵ֣ת לִ⁠תְפּ֔וֹר עֵ֥ת לַ⁠חֲשׁ֖וֹת וְ⁠עֵ֥ת לְ⁠דַבֵּֽר׃","ʻé֤ţ li⁠qĕr֨wòʻa֙ wĕ⁠ʻé֣ţ li⁠ţĕṗ֔wòr ʻé֥ţ la⁠ẖàş֖̌wòţ wĕ⁠ʻé֥ţ lĕ⁠dabéֽ̇r׃"],[3,8,"עֵ֤ת לֶֽ⁠אֱהֹב֙ וְ⁠עֵ֣ת לִ⁠שְׂנֹ֔א עֵ֥ת מִלְחָמָ֖ה וְ⁠עֵ֥ת שָׁלֽוֹם׃ס","ʻé֤ţ leֽ⁠ʼèhòb֙ wĕ⁠ʻé֣ţ li⁠şĕ̂nò֔ʼ ʻé֥ţ milĕẖámá֖h wĕ⁠ʻé֥ţ şá̌lֽwòm׃s"],[3,9,"מַה־יִּתְרוֹן֙ הָֽ⁠עוֹשֶׂ֔ה בַּ⁠אֲשֶׁ֖ר ה֥וּא עָמֵֽל׃","mah-yi̇ţĕrwòn֙ háֽ⁠ʻwòşê֔h bȧ⁠ʼàşě֖r h֥ẇʼ ʻáméֽl׃"],[3,10,"רָאִ֣יתִי אֶת־הָֽ⁠עִנְיָ֗ן אֲשֶׁ֨ר נָתַ֧ן אֱלֹהִ֛ים לִ⁠בְנֵ֥י הָ⁠אָדָ֖ם לַ⁠עֲנ֥וֹת בּֽ⁠וֹ׃","ráʼi֣yţiy ʼeţ-háֽ⁠ʻinĕyá֗n ʼàşě֨r náţa֧n ʼèlòhi֛ym li⁠bĕné֥y há⁠ʼádá֖m la⁠ʻàn֥wòţ ḃֽ⁠wò׃"],[3,11,"אֶת־הַ⁠כֹּ֥ל עָשָׂ֖ה יָפֶ֣ה בְ⁠עִתּ֑⁠וֹ גַּ֤ם אֶת־הָ⁠עֹלָם֙ נָתַ֣ן בְּ⁠לִבָּ֔⁠ם מִ⁠בְּלִ֞י אֲשֶׁ֧ר לֹא־יִמְצָ֣א הָ⁠אָדָ֗ם אֶת־הַֽ⁠מַּעֲשֶׂ֛ה אֲשֶׁר־עָשָׂ֥ה הָ⁠אֱלֹהִ֖ים מֵ⁠רֹ֥אשׁ וְ⁠עַד־סֽוֹף׃","ʼeţ-ha⁠kò֥̇l ʻáşá֖̂h yápe֣h bĕ⁠ʻiţ֑̇⁠wò gȧ֤m ʼeţ-há⁠ʻòlám֙ náţa֣n bĕ̇⁠libá̇֔⁠m mi⁠bĕ̇li֞y ʼàşě֧r lòʼ-yimĕẕá֣ʼ há⁠ʼádá֗m ʼeţ-haֽ⁠mȧʻàşê֛h ʼàşěr-ʻáşá֥̂h há⁠ʼèlòhi֖ym mé⁠rò֥ʼş̌ wĕ⁠ʻad-sֽwòp׃"],[3,12,"יָדַ֕עְתִּי כִּ֛י אֵ֥ין ט֖וֹב בָּ֑⁠ם כִּ֣י אִם־לִ⁠שְׂמ֔וֹחַ וְ⁠לַ⁠עֲשׂ֥וֹת ט֖וֹב בְּ⁠חַיָּֽי⁠ו׃","yáda֕ʻĕţi̇y ki֛̇y ʼé֥yn t֖wòb bá֑̇⁠m ki֣̇y ʼim-li⁠şĕ̂m֔wòẖa wĕ⁠la⁠ʻàş֥̂wòţ t֖wòb bĕ̇⁠ẖayáֽ̇y⁠w׃"],[3,13,"וְ⁠גַ֤ם כָּל־הָ⁠אָדָם֙ שֶׁ⁠יֹּאכַ֣ל וְ⁠שָׁתָ֔ה וְ⁠רָאָ֥ה ט֖וֹב בְּ⁠כָל־עֲמָל֑⁠וֹ מַתַּ֥ת אֱלֹהִ֖ים הִֽיא׃","wĕ⁠ga֤m ká̇l-há⁠ʼádám֙ şě⁠yò̇ʼka֣l wĕ⁠şá̌ţá֔h wĕ⁠ráʼá֥h t֖wòb bĕ̇⁠kál-ʻàmál֑⁠wò maţȧ֥ţ ʼèlòhi֖ym hiֽyʼ׃"],[3,14,"יָדַ֗עְתִּי כִּ֠י כָּל־אֲשֶׁ֨ר יַעֲשֶׂ֤ה הָ⁠אֱלֹהִים֙ ה֚וּא יִהְיֶ֣ה לְ⁠עוֹלָ֔ם עָלָי⁠ו֙ אֵ֣ין לְ⁠הוֹסִ֔יף וּ⁠מִמֶּ֖⁠נּוּ אֵ֣ין לִ⁠גְרֹ֑עַ וְ⁠הָ⁠אֱלֹהִ֣ים עָשָׂ֔ה שֶׁ⁠יִּֽרְא֖וּ מִ⁠לְּ⁠פָנָֽי⁠ו׃","yáda֗ʻĕţi̇y ki̇֠y ká̇l-ʼàşě֨r yaʻàşê֤h há⁠ʼèlòhiym֙ h֚ẇʼ yihĕye֣h lĕ⁠ʻwòlá֔m ʻáláy⁠w֙ ʼé֣yn lĕ⁠hwòsi֔yp ẇ⁠mimė֖⁠ṅẇ ʼé֣yn li⁠gĕrò֑ʻa wĕ⁠há⁠ʼèlòhi֣ym ʻáşá̂֔h şě⁠yiֽ̇rĕʼ֖ẇ mi⁠lĕ̇⁠pánáֽy⁠w׃"],[3,15,"מַה־שֶּֽׁ⁠הָיָה֙ כְּבָ֣ר ה֔וּא וַ⁠אֲשֶׁ֥ר לִ⁠הְי֖וֹת כְּבָ֣ר הָיָ֑ה וְ⁠הָ⁠אֱלֹהִ֖ים יְבַקֵּ֥שׁ אֶת־נִרְדָּֽף׃","mah-şėֽ̌⁠háyáh֙ kĕ̇bá֣r h֔ẇʼ wa⁠ʼàşě֥r li⁠hĕy֖wòţ kĕ̇bá֣r háyá֑h wĕ⁠há⁠ʼèlòhi֖ym yĕbaqé֥̇ş̌ ʼeţ-nirĕdáֽ̇p׃"],[3,16,"וְ⁠ע֥וֹד רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ מְק֤וֹם הַ⁠מִּשְׁפָּט֙ שָׁ֣מָּ⁠ה הָ⁠רֶ֔שַׁע וּ⁠מְק֥וֹם הַ⁠צֶּ֖דֶק שָׁ֥מָּ⁠ה הָ⁠רָֽשַׁע׃","wĕ⁠ʻ֥wòd ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ mĕq֤wòm ha⁠mi̇şĕ̌pá̇t֙ şá֣̌má̇⁠h há⁠re֔şǎʻ ẇ⁠mĕq֥wòm ha⁠ẕė֖deq şá֥̌má̇⁠h há⁠ráֽşǎʻ׃"],[3,17,"אָמַ֤רְתִּֽי אֲנִי֙ בְּ⁠לִבִּ֔⁠י אֶת־הַ⁠צַּדִּיק֙ וְ⁠אֶת־הָ֣⁠רָשָׁ֔ע יִשְׁפֹּ֖ט הָ⁠אֱלֹהִ֑ים כִּי־עֵ֣ת לְ⁠כָל־חֵ֔פֶץ וְ⁠עַ֥ל כָּל־הַֽ⁠מַּעֲשֶׂ֖ה שָֽׁם׃","ʼáma֤rĕţiֽ̇y ʼàniy֙ bĕ̇⁠libi̇֔⁠y ʼeţ-ha⁠ẕȧdi̇yq֙ wĕ⁠ʼeţ-há֣⁠ráşá̌֔ʻ yişĕ̌pò֖̇t há⁠ʼèlòhi֑ym ki̇y-ʻé֣ţ lĕ⁠kál-ẖé֔peẕ wĕ⁠ʻa֥l ká̇l-haֽ⁠mȧʻàşê֖h şáֽ̌m׃"],[3,18,"אָמַ֤רְתִּֽי אֲנִי֙ בְּ⁠לִבִּ֔⁠י עַל־דִּבְרַת֙ בְּנֵ֣י הָ⁠אָדָ֔ם לְ⁠בָרָ֖⁠ם הָ⁠אֱלֹהִ֑ים וְ⁠לִ⁠רְא֕וֹת שְׁ⁠הֶם־בְּהֵמָ֥ה הֵ֖מָּה לָ⁠הֶֽם׃","ʼáma֤rĕţiֽ̇y ʼàniy֙ bĕ̇⁠libi̇֔⁠y ʻal-di̇bĕraţ֙ bĕ̇né֣y há⁠ʼádá֔m lĕ⁠bárá֖⁠m há⁠ʼèlòhi֑ym wĕ⁠li⁠rĕʼ֕wòţ şĕ̌⁠hem-bĕ̇hémá֥h hé֖má̇h lá⁠heֽm׃"],[3,19,"כִּי֩ מִקְרֶ֨ה בְֽנֵי־הָ⁠אָדָ֜ם וּ⁠מִקְרֶ֣ה הַ⁠בְּהֵמָ֗ה וּ⁠מִקְרֶ֤ה אֶחָד֙ לָ⁠הֶ֔ם כְּ⁠מ֥וֹת זֶה֙ כֵּ֣ן מ֣וֹת זֶ֔ה וְ⁠ר֥וּחַ אֶחָ֖ד לַ⁠כֹּ֑ל וּ⁠מוֹתַ֨ר הָ⁠אָדָ֤ם מִן־הַ⁠בְּהֵמָה֙ אָ֔יִן כִּ֥י הַ⁠כֹּ֖ל הָֽבֶל׃","ki̇y֩ miqĕre֨h bĕֽnéy-há⁠ʼádá֜m ẇ⁠miqĕre֣h ha⁠bĕ̇hémá֗h ẇ⁠miqĕre֤h ʼeẖád֙ lá⁠he֔m kĕ̇⁠m֥wòţ zeh֙ ké֣̇n m֣wòţ ze֔h wĕ⁠r֥ẇẖa ʼeẖá֖d la⁠kò֑̇l ẇ⁠mwòţa֨r há⁠ʼádá֤m min-ha⁠bĕ̇hémáh֙ ʼá֔yin ki֥̇y ha⁠kò֖̇l háֽbel׃"],[3,20,"הַ⁠כֹּ֥ל הוֹלֵ֖ךְ אֶל־מָק֣וֹם אֶחָ֑ד הַ⁠כֹּל֙ הָיָ֣ה מִן־הֶֽ⁠עָפָ֔ר וְ⁠הַ⁠כֹּ֖ל שָׁ֥ב אֶל־הֶ⁠עָפָֽר׃","ha⁠kò֥̇l hwòlé֖kĕ ʼel-máq֣wòm ʼeẖá֑d ha⁠kò̇l֙ háyá֣h min-heֽ⁠ʻápá֔r wĕ⁠ha⁠kò֖̇l şá֥̌b ʼel-he⁠ʻápáֽr׃"],[3,21,"מִ֣י יוֹדֵ֗עַ ר֚וּחַ בְּנֵ֣י הָ⁠אָדָ֔ם הָ⁠עֹלָ֥ה הִ֖יא לְ⁠מָ֑עְלָ⁠ה וְ⁠ר֨וּחַ֙ הַ⁠בְּהֵמָ֔ה הַ⁠יֹּרֶ֥דֶת הִ֖יא לְ⁠מַ֥טָּה לָ⁠אָֽרֶץ׃","mi֣y ywòdé֗ʻa r֚ẇẖa bĕ̇né֣y há⁠ʼádá֔m há⁠ʻòlá֥h hi֖yʼ lĕ⁠má֑ʻĕlá⁠h wĕ⁠r֨ẇẖa֙ ha⁠bĕ̇hémá֔h ha⁠yò̇re֥deţ hi֖yʼ lĕ⁠ma֥tá̇h lá⁠ʼáֽreẕ׃"],[3,22,"וְ⁠רָאִ֗יתִי כִּ֣י אֵ֥ין טוֹב֙ מֵ⁠אֲשֶׁ֨ר יִשְׂמַ֤ח הָ⁠אָדָם֙ בְּֽ⁠מַעֲשָׂ֔י⁠ו כִּי־ה֖וּא חֶלְק֑⁠וֹ כִּ֣י מִ֤י יְבִיאֶ֨⁠נּוּ֙ לִ⁠רְא֔וֹת בְּ⁠מֶ֖ה שֶׁ⁠יִּהְיֶ֥ה אַחֲרָֽי⁠ו׃","wĕ⁠ráʼi֗yţiy ki֣̇y ʼé֥yn twòb֙ mé⁠ʼàşě֨r yişĕ̂ma֤ẖ há⁠ʼádám֙ bĕֽ̇⁠maʻàşá̂֔y⁠w ki̇y-h֖ẇʼ ẖelĕq֑⁠wò ki֣̇y mi֤y yĕbiyʼe֨⁠ṅẇ֙ li⁠rĕʼ֔wòţ bĕ̇⁠me֖h şě⁠yi̇hĕye֥h ʼaẖàráֽy⁠w׃"],[4,1,"וְ⁠שַׁ֣בְתִּֽי אֲנִ֗י וָ⁠אֶרְאֶה֙ אֶת־כָּל־הָ֣⁠עֲשֻׁקִ֔ים אֲשֶׁ֥ר נַעֲשִׂ֖ים תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וְ⁠הִנֵּ֣ה ׀ דִּמְעַ֣ת הָ⁠עֲשֻׁקִ֗ים וְ⁠אֵ֤ין לָ⁠הֶם֙ מְנַחֵ֔ם וּ⁠מִ⁠יַּ֤ד עֹֽשְׁקֵי⁠הֶם֙ כֹּ֔חַ וְ⁠אֵ֥ין לָ⁠הֶ֖ם מְנַחֵֽם׃","wĕ⁠şǎ֣bĕţiֽ̇y ʼàni֗y wá⁠ʼerĕʼeh֙ ʼeţ-ká̇l-há֣⁠ʻàşǔqi֔ym ʼàşě֥r naʻàşî֖ym ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ wĕ⁠hiné֣̇h ׀ di̇mĕʻa֣ţ há⁠ʻàşǔqi֗ym wĕ⁠ʼé֤yn lá⁠hem֙ mĕnaẖé֔m ẇ⁠mi⁠yȧ֤d ʻòֽşĕ̌qéy⁠hem֙ kò̇֔ẖa wĕ⁠ʼé֥yn lá⁠he֖m mĕnaẖéֽm׃"],[4,2,"וְ⁠שַׁבֵּ֧חַ אֲנִ֛י אֶת־הַ⁠מֵּתִ֖ים שֶׁ⁠כְּבָ֣ר מֵ֑תוּ מִן־הַ֣⁠חַיִּ֔ים אֲשֶׁ֛ר הֵ֥מָּה חַיִּ֖ים עֲדֶֽנָ⁠ה׃","wĕ⁠şǎbé֧̇ẖa ʼàni֛y ʼeţ-ha⁠mé̇ţi֖ym şě⁠kĕ̇bá֣r mé֑ţẇ min-ha֣⁠ẖayi̇֔ym ʼàşě֛r hé֥má̇h ẖayi֖̇ym ʻàdeֽná⁠h׃"],[4,3,"וְ⁠טוֹב֙ מִ⁠שְּׁנֵי⁠הֶ֔ם אֵ֥ת אֲשֶׁר־עֲדֶ֖ן לֹ֣א הָיָ֑ה אֲשֶׁ֤ר לֹֽא־רָאָה֙ אֶת־הַ⁠מַּעֲשֶׂ֣ה הָ⁠רָ֔ע אֲשֶׁ֥ר נַעֲשָׂ֖ה תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠twòb֙ mi⁠şĕ̇̌néy⁠he֔m ʼé֥ţ ʼàşěr-ʻàde֖n lò֣ʼ háyá֑h ʼàşě֤r lòֽʼ-ráʼáh֙ ʼeţ-ha⁠mȧʻàşê֣h há⁠rá֔ʻ ʼàşě֥r naʻàşá֖̂h ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[4,4,"וְ⁠רָאִ֨יתִֽי אֲנִ֜י אֶת־כָּל־עָמָ֗ל וְ⁠אֵת֙ כָּל־כִּשְׁר֣וֹן הַֽ⁠מַּעֲשֶׂ֔ה כִּ֛י הִ֥יא קִנְאַת־אִ֖ישׁ מֵ⁠רֵעֵ֑⁠הוּ גַּם־זֶ֥ה הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","wĕ⁠ráʼi֨yţiֽy ʼàni֜y ʼeţ-ká̇l-ʻámá֗l wĕ⁠ʼéţ֙ ká̇l-ki̇şĕ̌r֣wòn haֽ⁠mȧʻàşê֔h ki֛̇y hi֥yʼ qinĕʼaţ-ʼi֖yş̌ mé⁠réʻé֑⁠hẇ gȧm-ze֥h he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[4,5,"הַ⁠כְּסִיל֙ חֹבֵ֣ק אֶת־יָדָ֔י⁠ו וְ⁠אֹכֵ֖ל אֶת־בְּשָׂרֽ⁠וֹ׃","ha⁠kĕ̇siyl֙ ẖòbé֣q ʼeţ-yádá֔y⁠w wĕ⁠ʼòké֖l ʼeţ-bĕ̇şá̂rֽ⁠wò׃"],[4,6,"ט֕וֹב מְלֹ֥א כַ֖ף נָ֑חַת מִ⁠מְּלֹ֥א חָפְנַ֛יִם עָמָ֖ל וּ⁠רְע֥וּת רֽוּחַ׃","t֕wòb mĕlò֥ʼ ka֖p ná֑ẖaţ mi⁠mĕ̇lò֥ʼ ẖápĕna֛yim ʻámá֖l ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[4,7,"וְ⁠שַׁ֧בְתִּי אֲנִ֛י וָ⁠אֶרְאֶ֥ה הֶ֖בֶל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠şǎ֧bĕţi̇y ʼàni֛y wá⁠ʼerĕʼe֥h he֖bel ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[4,8,"יֵ֣שׁ אֶחָד֩ וְ⁠אֵ֨ין שֵׁנִ֜י גַּ֣ם בֵּ֧ן וָ⁠אָ֣ח אֵֽין־ל֗⁠וֹ וְ⁠אֵ֥ין קֵץ֙ לְ⁠כָל־עֲמָל֔⁠וֹ גַּם־עיני⁠ו לֹא־תִשְׂבַּ֣ע עֹ֑שֶׁר וּ⁠לְ⁠מִ֣י ׀ אֲנִ֣י עָמֵ֗ל וּ⁠מְחַסֵּ֤ר אֶת־נַפְשִׁ⁠י֙ מִ⁠טּוֹבָ֔ה גַּם־זֶ֥ה הֶ֛בֶל וְ⁠עִנְיַ֥ן רָ֖ע הֽוּא׃","yé֣ş̌ ʼeẖád֩ wĕ⁠ʼé֨yn şé̌ni֜y gȧ֣m bé֧̇n wá⁠ʼá֣ẖ ʼéֽyn-l֗⁠wò wĕ⁠ʼé֥yn qéẕ֙ lĕ⁠kál-ʻàmál֔⁠wò gȧm-ʻyny⁠w lòʼ-ţişĕ̂bȧ֣ʻ ʻò֑şěr ẇ⁠lĕ⁠mi֣y ׀ ʼàni֣y ʻámé֗l ẇ⁠mĕẖasé֤̇r ʼeţ-napĕşǐ⁠y֙ mi⁠ṫwòbá֔h gȧm-ze֥h he֛bel wĕ⁠ʻinĕya֥n rá֖ʻ hֽẇʼ׃"],[4,9,"טוֹבִ֥ים הַ⁠שְּׁנַ֖יִם מִן־הָ⁠אֶחָ֑ד אֲשֶׁ֧ר יֵשׁ־לָ⁠הֶ֛ם שָׂכָ֥ר ט֖וֹב בַּ⁠עֲמָלָֽ⁠ם׃","twòbi֥ym ha⁠şĕ̇̌na֖yim min-há⁠ʼeẖá֑d ʼàşě֧r yéş̌-lá⁠he֛m şá̂ká֥r t֖wòb bȧ⁠ʻàmáláֽ⁠m׃"],[4,10,"כִּ֣י אִם־יִפֹּ֔לוּ הָ⁠אֶחָ֖ד יָקִ֣ים אֶת־חֲבֵר֑⁠וֹ וְ⁠אִ֣י⁠ל֗⁠וֹ הָֽ⁠אֶחָד֙ שֶׁ⁠יִּפּ֔וֹל וְ⁠אֵ֥ין שֵׁנִ֖י לַ⁠הֲקִימֽ⁠וֹ׃","ki֣̇y ʼim-yipò̇֔lẇ há⁠ʼeẖá֖d yáqi֣ym ʼeţ-ẖàbér֑⁠wò wĕ⁠ʼi֣y⁠l֗⁠wò háֽ⁠ʼeẖád֙ şě⁠yi̇ṗ֔wòl wĕ⁠ʼé֥yn şé̌ni֖y la⁠hàqiymֽ⁠wò׃"],[4,11,"גַּ֛ם אִם־יִשְׁכְּב֥וּ שְׁנַ֖יִם וְ⁠חַ֣ם לָ⁠הֶ֑ם וּ⁠לְ⁠אֶחָ֖ד אֵ֥יךְ יֵחָֽם׃","gȧ֛m ʼim-yişĕ̌kĕ̇b֥ẇ şĕ̌na֖yim wĕ⁠ẖa֣m lá⁠he֑m ẇ⁠lĕ⁠ʼeẖá֖d ʼé֥ykĕ yéẖáֽm׃"],[4,12,"וְ⁠אִֽם־יִתְקְפ⁠וֹ֙ הָ⁠אֶחָ֔ד הַ⁠שְּׁנַ֖יִם יַעַמְד֣וּ נֶגְדּ֑⁠וֹ וְ⁠הַ⁠חוּט֙ הַֽ⁠מְשֻׁלָּ֔שׁ לֹ֥א בִ⁠מְהֵרָ֖ה יִנָּתֵֽק׃","wĕ⁠ʼiֽm-yiţĕqĕp⁠wò֙ há⁠ʼeẖá֔d ha⁠şĕ̇̌na֖yim yaʻamĕd֣ẇ negĕḋ֑⁠wò wĕ⁠ha⁠ẖẇt֙ haֽ⁠mĕşǔlá̇֔ş̌ lò֥ʼ bi⁠mĕhérá֖h yiná̇ţéֽq׃"],[4,13,"ט֛וֹב יֶ֥לֶד מִסְכֵּ֖ן וְ⁠חָכָ֑ם מִ⁠מֶּ֤לֶךְ זָקֵן֙ וּ⁠כְסִ֔יל אֲשֶׁ֛ר לֹא־יָדַ֥ע לְ⁠הִזָּהֵ֖ר עֽוֹד׃","t֛wòb ye֥led misĕké֖̇n wĕ⁠ẖáká֑m mi⁠mė֤lekĕ záqén֙ ẇ⁠kĕsi֔yl ʼàşě֛r lòʼ-yáda֥ʻ lĕ⁠hizá̇hé֖r ʻֽwòd׃"],[4,14,"כִּֽי־מִ⁠בֵּ֥ית הָ⁠סוּרִ֖ים יָצָ֣א לִ⁠מְלֹ֑ךְ כִּ֛י גַּ֥ם בְּ⁠מַלְכוּת֖⁠וֹ נוֹלַ֥ד רָֽשׁ׃","kiֽ̇y-mi⁠bé֥̇yţ há⁠sẇri֖ym yáẕá֣ʼ li⁠mĕlò֑kĕ ki֛̇y gȧ֥m bĕ̇⁠malĕkẇţ֖⁠wò nwòla֥d ráֽş̌׃"],[4,15,"רָאִ֨יתִי֙ אֶת־כָּל־הַ֣⁠חַיִּ֔ים הַֽ⁠מְהַלְּכִ֖ים תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ עִ֚ם הַ⁠יֶּ֣לֶד הַ⁠שֵּׁנִ֔י אֲשֶׁ֥ר יַעֲמֹ֖ד תַּחְתָּֽי⁠ו׃","ráʼi֨yţiy֙ ʼeţ-ká̇l-ha֣⁠ẖayi̇֔ym haֽ⁠mĕhalĕ̇ki֖ym ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ʻi֚m ha⁠yė֣led ha⁠şé̇̌ni֔y ʼàşě֥r yaʻàmò֖d ţȧẖĕţáֽ̇y⁠w׃"],[4,16,"אֵֽין־קֵ֣ץ לְ⁠כָל־הָ⁠עָ֗ם לְ⁠כֹ֤ל אֲשֶׁר־הָיָה֙ לִ⁠פְנֵי⁠הֶ֔ם גַּ֥ם הָ⁠אַחֲרוֹנִ֖ים לֹ֣א יִשְׂמְחוּ־ב֑⁠וֹ כִּֽי־גַם־זֶ֥ה הֶ֖בֶל וְ⁠רַעְי֥וֹן רֽוּחַ׃","ʼéֽyn-qé֣ẕ lĕ⁠kál-há⁠ʻá֗m lĕ⁠kò֤l ʼàşěr-háyáh֙ li⁠pĕnéy⁠he֔m gȧ֥m há⁠ʼaẖàrwòni֖ym lò֣ʼ yişĕ̂mĕẖẇ-b֑⁠wò kiֽ̇y-gam-ze֥h he֖bel wĕ⁠raʻĕy֥wòn rֽẇẖa׃"],[5,1,"שְׁמֹ֣ר רגלי⁠ך כַּ⁠אֲשֶׁ֤ר תֵּלֵךְ֙ אֶל־בֵּ֣ית הָ⁠אֱלֹהִ֔ים וְ⁠קָר֣וֹב לִ⁠שְׁמֹ֔עַ מִ⁠תֵּ֥ת הַ⁠כְּסִילִ֖ים זָ֑בַח כִּֽי־אֵינָ֥⁠ם יוֹדְעִ֖ים לַ⁠עֲשׂ֥וֹת רָֽע׃","şĕ̌mò֣r rgly⁠k kȧ⁠ʼàşě֤r ţé̇lékĕ֙ ʼel-bé֣̇yţ há⁠ʼèlòhi֔ym wĕ⁠qár֣wòb li⁠şĕ̌mò֔ʻa mi⁠ţé֥̇ţ ha⁠kĕ̇siyli֖ym zá֑baẖ kiֽ̇y-ʼéyná֥⁠m ywòdĕʻi֖ym la⁠ʻàş֥̂wòţ ráֽʻ׃"],[5,2,"אַל־תְּבַהֵ֨ל עַל־פִּ֜י⁠ךָ וְ⁠לִבְּ⁠ךָ֧ אַל־יְמַהֵ֛ר לְ⁠הוֹצִ֥יא דָבָ֖ר לִ⁠פְנֵ֣י הָ⁠אֱלֹהִ֑ים כִּ֣י הָ⁠אֱלֹהִ֤ים בַּ⁠שָּׁמַ֨יִם֙ וְ⁠אַתָּ֣ה עַל־הָ⁠אָ֔רֶץ עַֽל־כֵּ֛ן יִהְי֥וּ דְבָרֶ֖י⁠ךָ מְעַטִּֽים׃","ʼal-ţĕ̇bahé֨l ʻal-pi̇֜y⁠ká wĕ⁠libĕ̇⁠ká֧ ʼal-yĕmahé֛r lĕ⁠hwòẕi֥yʼ dábá֖r li⁠pĕné֣y há⁠ʼèlòhi֑ym ki֣̇y há⁠ʼèlòhi֤ym bȧ⁠şá̇̌ma֨yim֙ wĕ⁠ʼaţá֣̇h ʻal-há⁠ʼá֔reẕ ʻaֽl-ké֛̇n yihĕy֥ẇ dĕbáre֖y⁠ká mĕʻatiֽ̇ym׃"],[5,3,"כִּ֛י בָּ֥א הַ⁠חֲל֖וֹם בְּ⁠רֹ֣ב עִנְיָ֑ן וְ⁠ק֥וֹל כְּסִ֖יל בְּ⁠רֹ֥ב דְּבָרִֽים׃","ki֛̇y bá֥̇ʼ ha⁠ẖàl֖wòm bĕ̇⁠rò֣b ʻinĕyá֑n wĕ⁠q֥wòl kĕ̇si֖yl bĕ̇⁠rò֥b dĕ̇báriֽym׃"],[5,4,"כַּ⁠אֲשֶׁר֩ תִּדֹּ֨ר נֶ֜דֶר לֵֽ⁠אלֹהִ֗ים אַל־תְּאַחֵר֙ לְ⁠שַׁלְּמ֔⁠וֹ כִּ֛י אֵ֥ין חֵ֖פֶץ בַּ⁠כְּסִילִ֑ים אֵ֥ת אֲשֶׁר־תִּדֹּ֖ר שַׁלֵּֽם׃","kȧ⁠ʼàşěr֩ ţi̇dò̇֨r ne֜der lֽé⁠ʼlòhi֗ym ʼal-ţĕ̇ʼaẖér֙ lĕ⁠şǎlĕ̇m֔⁠wò ki֛̇y ʼé֥yn ẖé֖peẕ bȧ⁠kĕ̇siyli֑ym ʼé֥ţ ʼàşěr-ţi̇dò֖̇r şǎléֽ̇m׃"],[5,5,"ט֖וֹב אֲשֶׁ֣ר לֹֽא־תִדֹּ֑ר מִ⁠שֶׁ⁠תִּדּ֖וֹר וְ⁠לֹ֥א תְשַׁלֵּֽם׃","t֖wòb ʼàşě֣r lòֽʼ-ţidò֑̇r mi⁠şě⁠ţi̇ḋ֖wòr wĕ⁠lò֥ʼ ţĕşǎléֽ̇m׃"],[5,6,"אַל־תִּתֵּ֤ן אֶת־פִּ֨י⁠ךָ֙ לַ⁠חֲטִ֣יא אֶת־בְּשָׂרֶ֔⁠ךָ וְ⁠אַל־תֹּאמַר֙ לִ⁠פְנֵ֣י הַ⁠מַּלְאָ֔ךְ כִּ֥י שְׁגָגָ֖ה הִ֑יא לָ֣⁠מָּה יִקְצֹ֤ף הָֽ⁠אֱלֹהִים֙ עַל־קוֹלֶ֔⁠ךָ וְ⁠חִבֵּ֖ל אֶת־מַעֲשֵׂ֥ה יָדֶֽי⁠ךָ׃","ʼal-ţi̇ţé֤̇n ʼeţ-pi̇֨y⁠ká֙ la⁠ẖàti֣yʼ ʼeţ-bĕ̇şá̂re֔⁠ká wĕ⁠ʼal-ţò̇ʼmar֙ li⁠pĕné֣y ha⁠mȧlĕʼá֔kĕ ki֥̇y şĕ̌gágá֖h hi֑yʼ lá֣⁠má̇h yiqĕẕò֤p háֽ⁠ʼèlòhiym֙ ʻal-qwòle֔⁠ká wĕ⁠ẖibé֖̇l ʼeţ-maʻàşé֥̂h yádeֽy⁠ká׃"],[5,7,"כִּ֣י בְ⁠רֹ֤ב חֲלֹמוֹת֙ וַ⁠הֲבָלִ֔ים וּ⁠דְבָרִ֖ים הַרְבֵּ֑ה כִּ֥י אֶת־הָ⁠אֱלֹהִ֖ים יְרָֽא׃","ki֣̇y bĕ⁠rò֤b ẖàlòmwòţ֙ wa⁠hàbáli֔ym ẇ⁠dĕbári֖ym harĕbé֑̇h ki֥̇y ʼeţ-há⁠ʼèlòhi֖ym yĕráֽʼ׃"],[5,8,"אִם־עֹ֣שֶׁק רָ֠שׁ וְ⁠גֵ֨זֶל מִשְׁפָּ֤ט וָ⁠צֶ֨דֶק֙ תִּרְאֶ֣ה בַ⁠מְּדִינָ֔ה אַל־תִּתְמַ֖הּ עַל־הַ⁠חֵ֑פֶץ כִּ֣י גָבֹ֜הַּ מֵ⁠עַ֤ל גָּבֹ֨הַ֙ שֹׁמֵ֔ר וּ⁠גְבֹהִ֖ים עֲלֵי⁠הֶֽם׃","ʼim-ʻò֣şěq rá֠ş̌ wĕ⁠gé֨zel mişĕ̌pá֤̇t wá⁠ẕe֨deq֙ ţi̇rĕʼe֣h ba⁠mĕ̇diyná֔h ʼal-ţi̇ţĕma֖ḣ ʻal-ha⁠ẖé֑peẕ ki֣̇y gábò֜hȧ mé⁠ʻa֤l gá̇bò֨ha֙ şò̌mé֔r ẇ⁠gĕbòhi֖ym ʻàléy⁠heֽm׃"],[5,9,"וְ⁠יִתְר֥וֹן אֶ֖רֶץ בַּ⁠כֹּ֣ל היא מֶ֥לֶךְ לְ⁠שָׂדֶ֖ה נֶעֱבָֽד׃","wĕ⁠yiţĕr֥wòn ʼe֖reẕ bȧ⁠kò֣̇l hyʼ me֥lekĕ lĕ⁠şá̂de֖h neʻèbáֽd׃"],[5,10,"אֹהֵ֥ב כֶּ֨סֶף֙ לֹא־יִשְׂבַּ֣ע כֶּ֔סֶף וּ⁠מִֽי־אֹהֵ֥ב בֶּ⁠הָמ֖וֹן לֹ֣א תְבוּאָ֑ה גַּם־זֶ֖ה הָֽבֶל׃","ʼòhé֥b kė֨sep֙ lòʼ-yişĕ̂bȧ֣ʻ kė֔sep ẇ⁠miֽy-ʼòhé֥b bė⁠hám֖wòn lò֣ʼ ţĕbẇʼá֑h gȧm-ze֖h háֽbel׃"],[5,11,"בִּ⁠רְבוֹת֙ הַ⁠טּוֹבָ֔ה רַבּ֖וּ אוֹכְלֶ֑י⁠הָ וּ⁠מַה־כִּשְׁרוֹן֙ לִ⁠בְעָלֶ֔י⁠הָ כִּ֖י אִם־ראית עֵינָֽי⁠ו׃","bi̇⁠rĕbwòţ֙ ha⁠ṫwòbá֔h raḃ֖ẇ ʼwòkĕle֑y⁠há ẇ⁠mah-ki̇şĕ̌rwòn֙ li⁠bĕʻále֔y⁠há ki֖̇y ʼim-rʼyţ ʻéynáֽy⁠w׃"],[5,12,"מְתוּקָה֙ שְׁנַ֣ת הָ⁠עֹבֵ֔ד אִם־מְעַ֥ט וְ⁠אִם־הַרְבֵּ֖ה יֹאכֵ֑ל וְ⁠הַ⁠שָּׂבָע֙ לֶֽ⁠עָשִׁ֔יר אֵינֶ֛⁠נּוּ מַנִּ֥יחַֽ ל֖⁠וֹ לִ⁠ישֽׁוֹן׃","mĕţẇqáh֙ şĕ̌na֣ţ há⁠ʻòbé֔d ʼim-mĕʻa֥t wĕ⁠ʼim-harĕbé֖̇h yòʼké֑l wĕ⁠ha⁠şá̇̂báʻ֙ leֽ⁠ʻáşǐ֔yr ʼéyne֛⁠ṅẇ mani֥̇yẖaֽ l֖⁠wò li⁠yşֽ̌wòn׃"],[5,13,"יֵ֚שׁ רָעָ֣ה חוֹלָ֔ה רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ עֹ֛שֶׁר שָׁמ֥וּר לִ⁠בְעָלָ֖י⁠ו לְ⁠רָעָתֽ⁠וֹ׃","yé֚ş̌ ráʻá֣h ẖwòlá֔h ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ʻò֛şěr şá̌m֥ẇr li⁠bĕʻálá֖y⁠w lĕ⁠ráʻáţֽ⁠wò׃"],[5,14,"וְ⁠אָבַ֛ד הָ⁠עֹ֥שֶׁר הַ⁠ה֖וּא בְּ⁠עִנְיַ֣ן רָ֑ע וְ⁠הוֹלִ֣יד בֵּ֔ן וְ⁠אֵ֥ין בְּ⁠יָד֖⁠וֹ מְאֽוּמָה׃","wĕ⁠ʼába֛d há⁠ʻò֥şěr ha⁠h֖ẇʼ bĕ̇⁠ʻinĕya֣n rá֑ʻ wĕ⁠hwòli֣yd bé̇֔n wĕ⁠ʼé֥yn bĕ̇⁠yád֖⁠wò mĕʼֽẇmáh׃"],[5,15,"כַּ⁠אֲשֶׁ֤ר יָצָא֙ מִ⁠בֶּ֣טֶן אִמּ֔⁠וֹ עָר֛וֹם יָשׁ֥וּב לָ⁠לֶ֖כֶת כְּ⁠שֶׁ⁠בָּ֑א וּ⁠מְא֨וּמָה֙ לֹא־יִשָּׂ֣א בַ⁠עֲמָל֔⁠וֹ שֶׁ⁠יֹּלֵ֖ךְ בְּ⁠יָדֽ⁠וֹ׃","kȧ⁠ʼàşě֤r yáẕáʼ֙ mi⁠bė֣ten ʼiṁ֔⁠wò ʻár֛wòm yáş֥̌ẇb lá⁠le֖keţ kĕ̇⁠şě⁠bá֑̇ʼ ẇ⁠mĕʼ֨ẇmáh֙ lòʼ-yişá֣̇̂ʼ ba⁠ʻàmál֔⁠wò şě⁠yò̇lé֖kĕ bĕ̇⁠yádֽ⁠wò׃"],[5,16,"וְ⁠גַם־זֹה֙ רָעָ֣ה חוֹלָ֔ה כָּ⁠ל־עֻמַּ֥ת שֶׁ⁠בָּ֖א כֵּ֣ן יֵלֵ֑ךְ וּ⁠מַה־יִּתְר֣וֹן ל֔⁠וֹ שֶֽׁ⁠יַּעֲמֹ֖ל לָ⁠רֽוּחַ׃","wĕ⁠gam-zòh֙ ráʻá֣h ẖwòlá֔h ká̇⁠l-ʻumȧ֥ţ şě⁠bá֖̇ʼ ké֣̇n yélé֑kĕ ẇ⁠mah-yi̇ţĕr֣wòn l֔⁠wò şěֽ⁠yȧʻàmò֖l lá⁠rֽẇẖa׃"],[5,17,"גַּ֥ם כָּל־יָמָ֖י⁠ו בַּ⁠חֹ֣שֶׁךְ יֹאכֵ֑ל וְ⁠כָעַ֥ס הַרְבֵּ֖ה וְ⁠חָלְי֥⁠וֹ וָ⁠קָֽצֶף׃","gȧ֥m ká̇l-yámá֖y⁠w bȧ⁠ẖò֣şěkĕ yòʼké֑l wĕ⁠káʻa֥s harĕbé֖̇h wĕ⁠ẖálĕy֥⁠wò wá⁠qáֽẕep׃"],[5,18,"הִנֵּ֞ה אֲשֶׁר־רָאִ֣יתִי אָ֗נִי ט֣וֹב אֲשֶׁר־יָפֶ֣ה לֶֽ⁠אֶכוֹל־וְ֠⁠לִ⁠שְׁתּוֹת וְ⁠לִ⁠רְא֨וֹת טוֹבָ֜ה בְּ⁠כָל־עֲמָל֣⁠וֹ ׀ שֶׁ⁠יַּעֲמֹ֣ל תַּֽחַת־הַ⁠שֶּׁ֗מֶשׁ מִסְפַּ֧ר יְמֵי־חי⁠ו אֲשֶׁר־נָֽתַן־ל֥⁠וֹ הָ⁠אֱלֹהִ֖ים כִּי־ה֥וּא חֶלְקֽ⁠וֹ׃","hiné̇֞h ʼàşěr-ráʼi֣yţiy ʼá֗niy t֣wòb ʼàşěr-yápe֣h leֽ⁠ʼekwòl-wĕ֠⁠li⁠şĕ̌ţ̇wòţ wĕ⁠li⁠rĕʼ֨wòţ twòbá֜h bĕ̇⁠kál-ʻàmál֣⁠wò ׀ şě⁠yȧʻàmò֣l ţȧֽẖaţ-ha⁠şė̌֗meş̌ misĕpȧ֧r yĕméy-ẖy⁠w ʼàşěr-náֽţan-l֥⁠wò há⁠ʼèlòhi֖ym ki̇y-h֥ẇʼ ẖelĕqֽ⁠wò׃"],[5,19,"גַּ֣ם כָּֽל־הָ⁠אָדָ֡ם אֲשֶׁ֣ר נָֽתַן־ל֣⁠וֹ הָ⁠אֱלֹהִים֩ עֹ֨שֶׁר וּ⁠נְכָסִ֜ים וְ⁠הִשְׁלִיט֨⁠וֹ לֶ⁠אֱכֹ֤ל מִמֶּ֨⁠נּוּ֙ וְ⁠לָ⁠שֵׂ֣את אֶת־חֶלְק֔⁠וֹ וְ⁠לִ⁠שְׂמֹ֖חַ בַּ⁠עֲמָל֑⁠וֹ זֹ֕ה מַתַּ֥ת אֱלֹהִ֖ים הִֽיא׃","gȧ֣m káֽ̇l-há⁠ʼádá֡m ʼàşě֣r náֽţan-l֣⁠wò há⁠ʼèlòhiym֩ ʻò֨şěr ẇ⁠nĕkási֜ym wĕ⁠hişĕ̌liyt֨⁠wò le⁠ʼèkò֤l mimė֨⁠ṅẇ֙ wĕ⁠lá⁠şé֣̂ʼţ ʼeţ-ẖelĕq֔⁠wò wĕ⁠li⁠şĕ̂mò֖ẖa bȧ⁠ʻàmál֑⁠wò zò֕h maţȧ֥ţ ʼèlòhi֖ym hiֽyʼ׃"],[5,20,"כִּ֚י לֹ֣א הַרְבֵּ֔ה יִזְכֹּ֖ר אֶת־יְמֵ֣י חַיָּ֑י⁠ו כִּ֧י הָ⁠אֱלֹהִ֛ים מַעֲנֶ֖ה בְּ⁠שִׂמְחַ֥ת לִבּֽ⁠וֹ׃","ki֚̇y lò֣ʼ harĕbé̇֔h yizĕkò֖̇r ʼeţ-yĕmé֣y ẖayá֑̇y⁠w ki֧̇y há⁠ʼèlòhi֛ym maʻàne֖h bĕ̇⁠şîmĕẖa֥ţ liḃֽ⁠wò׃"],[6,1,"יֵ֣שׁ רָעָ֔ה אֲשֶׁ֥ר רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וְ⁠רַבָּ֥ה הִ֖יא עַל־הָ⁠אָדָֽם׃","yé֣ş̌ ráʻá֔h ʼàşě֥r ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ wĕ⁠rabá֥̇h hi֖yʼ ʻal-há⁠ʼádáֽm׃"],[6,2,"אִ֣ישׁ אֲשֶׁ֣ר יִתֶּן־ל֣⁠וֹ הָ⁠אֱלֹהִ֡ים עֹשֶׁר֩ וּ⁠נְכָסִ֨ים וְ⁠כָב֜וֹד וְֽ⁠אֵינֶ֨⁠נּוּ חָסֵ֥ר לְ⁠נַפְשׁ֣⁠וֹ ׀ מִ⁠כֹּ֣ל אֲשֶׁר־יִתְאַוֶּ֗ה וְ⁠לֹֽא־יַשְׁלִיטֶ֤⁠נּוּ הָֽ⁠אֱלֹהִים֙ לֶ⁠אֱכֹ֣ל מִמֶּ֔⁠נּוּ כִּ֛י אִ֥ישׁ נָכְרִ֖י יֹֽאכֲלֶ֑⁠נּוּ זֶ֥ה הֶ֛בֶל וָ⁠חֳלִ֥י רָ֖ע הֽוּא׃","ʼi֣yş̌ ʼàşě֣r yiţėn-l֣⁠wò há⁠ʼèlòhi֡ym ʻòşěr֩ ẇ⁠nĕkási֨ym wĕ⁠káb֜wòd wĕֽ⁠ʼéyne֨⁠ṅẇ ẖásé֥r lĕ⁠napĕş֣̌⁠wò ׀ mi⁠kò֣̇l ʼàşěr-yiţĕʼawė֗h wĕ⁠lòֽʼ-yaşĕ̌liyte֤⁠ṅẇ háֽ⁠ʼèlòhiym֙ le⁠ʼèkò֣l mimė֔⁠ṅẇ ki֛̇y ʼi֥yş̌ nákĕri֖y yòֽʼkàle֑⁠ṅẇ ze֥h he֛bel wá⁠ẖoli֥y rá֖ʻ hֽẇʼ׃"],[6,3,"אִם־יוֹלִ֣יד אִ֣ישׁ מֵאָ֡ה וְ⁠שָׁנִים֩ רַבּ֨וֹת יִֽחְיֶ֜ה וְ⁠רַ֣ב ׀ שֶׁ⁠יִּהְי֣וּ יְמֵֽי־שָׁנָ֗י⁠ו וְ⁠נַפְשׁ⁠וֹ֙ לֹא־תִשְׂבַּ֣ע מִן־הַ⁠טּוֹבָ֔ה וְ⁠גַם־קְבוּרָ֖ה לֹא־הָ֣יְתָה לּ֑⁠וֹ אָמַ֕רְתִּי ט֥וֹב מִמֶּ֖⁠נּוּ הַ⁠נָּֽפֶל׃","ʼim-ywòli֣yd ʼi֣yş̌ méʼá֡h wĕ⁠şá̌niym֩ raḃ֨wòţ yiֽẖĕye֜h wĕ⁠ra֣b ׀ şě⁠yi̇hĕy֣ẇ yĕméֽy-şá̌ná֗y⁠w wĕ⁠napĕş̌⁠wò֙ lòʼ-ţişĕ̂bȧ֣ʻ min-ha⁠ṫwòbá֔h wĕ⁠gam-qĕbẇrá֖h lòʼ-há֣yĕţáh l֑̇⁠wò ʼáma֕rĕţi̇y t֥wòb mimė֖⁠ṅẇ ha⁠náֽ̇pel׃"],[6,4,"כִּֽי־בַ⁠הֶ֥בֶל בָּ֖א וּ⁠בַ⁠חֹ֣שֶׁךְ יֵלֵ֑ךְ וּ⁠בַ⁠חֹ֖שֶׁךְ שְׁמ֥⁠וֹ יְכֻסֶּֽה׃","kiֽ̇y-ba⁠he֥bel bá֖̇ʼ ẇ⁠ba⁠ẖò֣şěkĕ yélé֑kĕ ẇ⁠ba⁠ẖò֖şěkĕ şĕ̌m֥⁠wò yĕkusėֽh׃"],[6,5,"גַּם־שֶׁ֥מֶשׁ לֹא־רָאָ֖ה וְ⁠לֹ֣א יָדָ֑ע נַ֥חַת לָ⁠זֶ֖ה מִ⁠זֶּֽה׃","gȧm-şě֥meş̌ lòʼ-ráʼá֖h wĕ⁠lò֣ʼ yádá֑ʻ na֥ẖaţ lá⁠ze֖h mi⁠zėֽh׃"],[6,6,"וְ⁠אִלּ֣וּ חָיָ֗ה אֶ֤לֶף שָׁנִים֙ פַּעֲמַ֔יִם וְ⁠טוֹבָ֖ה לֹ֣א רָאָ֑ה הֲ⁠לֹ֛א אֶל־מָק֥וֹם אֶחָ֖ד הַ⁠כֹּ֥ל הוֹלֵֽךְ׃","wĕ⁠ʼil֣̇ẇ ẖáyá֗h ʼe֤lep şá̌niym֙ pȧʻàma֔yim wĕ⁠twòbá֖h lò֣ʼ ráʼá֑h hà⁠lò֛ʼ ʼel-máq֥wòm ʼeẖá֖d ha⁠kò֥̇l hwòléֽkĕ׃"],[6,7,"כָּל־עֲמַ֥ל הָ⁠אָדָ֖ם לְ⁠פִ֑י⁠הוּ וְ⁠גַם־הַ⁠נֶּ֖פֶשׁ לֹ֥א תִמָּלֵֽא׃","ká̇l-ʻàma֥l há⁠ʼádá֖m lĕ⁠pi֑y⁠hẇ wĕ⁠gam-ha⁠nė֖peş̌ lò֥ʼ ţimá̇léֽʼ׃"],[6,8,"כִּ֛י מַה־יּוֹתֵ֥ר לֶ⁠חָכָ֖ם מִֽן־הַ⁠כְּסִ֑יל מַה־לֶּ⁠עָנִ֣י יוֹדֵ֔עַ לַ⁠הֲלֹ֖ךְ נֶ֥גֶד הַ⁠חַיִּֽים׃","ki֛̇y mah-ẏwòţé֥r le⁠ẖáká֖m miֽn-ha⁠kĕ̇si֑yl mah-lė⁠ʻáni֣y ywòdé֔ʻa la⁠hàlò֖kĕ ne֥ged ha⁠ẖayiֽ̇ym׃"],[6,9,"ט֛וֹב מַרְאֵ֥ה עֵינַ֖יִם מֵֽ⁠הֲלָךְ־נָ֑פֶשׁ גַּם־זֶ֥ה הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","t֛wòb marĕʼé֥h ʻéyna֖yim méֽ⁠hàlákĕ-ná֑peş̌ gȧm-ze֥h he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[6,10,"מַה־שֶּֽׁ⁠הָיָ֗ה כְּבָר֙ נִקְרָ֣א שְׁמ֔⁠וֹ וְ⁠נוֹדָ֖ע אֲשֶׁר־ה֣וּא אָדָ֑ם וְ⁠לֹא־יוּכַ֣ל לָ⁠דִ֔ין עִ֥ם ש⁠התקיף מִמֶּֽ⁠נּוּ׃","mah-şėֽ̌⁠háyá֗h kĕ̇bár֙ niqĕrá֣ʼ şĕ̌m֔⁠wò wĕ⁠nwòdá֖ʻ ʼàşěr-h֣ẇʼ ʼádá֑m wĕ⁠lòʼ-yẇka֣l lá⁠di֔yn ʻi֥m ş⁠hţqyp mimėֽ⁠ṅẇ׃"],[6,11,"כִּ֛י יֵשׁ־דְּבָרִ֥ים הַרְבֵּ֖ה מַרְבִּ֣ים הָ֑בֶל מַה־יֹּתֵ֖ר לָ⁠אָדָֽם׃","ki֛̇y yéş̌-dĕ̇bári֥ym harĕbé֖̇h marĕbi֣̇ym há֑bel mah-yò̇ţé֖r lá⁠ʼádáֽm׃"],[6,12,"כִּ֣י מִֽי־יוֹדֵעַ֩ מַה־טּ֨וֹב לָֽ⁠אָדָ֜ם בַּֽ⁠חַיִּ֗ים מִסְפַּ֛ר יְמֵי־חַיֵּ֥י הֶבְל֖⁠וֹ וְ⁠יַעֲשֵׂ֣⁠ם כַּ⁠צֵּ֑ל אֲשֶׁר֙ מִֽי־יַגִּ֣יד לָֽ⁠אָדָ֔ם מַה־יִּהְיֶ֥ה אַחֲרָ֖י⁠ו תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","ki֣̇y miֽy-ywòdéʻa֩ mah-ṫ֨wòb láֽ⁠ʼádá֜m bȧֽ⁠ẖayi̇֗ym misĕpȧ֛r yĕméy-ẖayé֥̇y hebĕl֖⁠wò wĕ⁠yaʻàşé֣̂⁠m kȧ⁠ẕé֑̇l ʼàşěr֙ miֽy-yagi֣̇yd láֽ⁠ʼádá֔m mah-yi̇hĕye֥h ʼaẖàrá֖y⁠w ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[7,1,"ט֥וֹב שֵׁ֖ם מִ⁠שֶּׁ֣מֶן ט֑וֹב וְ⁠י֣וֹם הַ⁠מָּ֔וֶת מִ⁠יּ֖וֹם הִוָּלְדֽ⁠וֹ׃","t֥wòb şé֖̌m mi⁠şė֣̌men t֑wòb wĕ⁠y֣wòm ha⁠má̇֔weţ mi⁠ẏ֖wòm hiwá̇lĕdֽ⁠wò׃"],[7,2,"ט֞וֹב לָ⁠לֶ֣כֶת אֶל־בֵּֽית־אֵ֗בֶל מִ⁠לֶּ֨כֶת֙ אֶל־בֵּ֣ית מִשְׁתֶּ֔ה בַּ⁠אֲשֶׁ֕ר ה֖וּא ס֣וֹף כָּל־הָ⁠אָדָ֑ם וְ⁠הַ⁠חַ֖י יִתֵּ֥ן אֶל־לִבּֽ⁠וֹ׃","t֞wòb lá⁠le֣keţ ʼel-béֽ̇yţ-ʼé֗bel mi⁠lė֨keţ֙ ʼel-bé֣̇yţ mişĕ̌ţė֔h bȧ⁠ʼàşě֕r h֖ẇʼ s֣wòp ká̇l-há⁠ʼádá֑m wĕ⁠ha⁠ẖa֖y yiţé֥̇n ʼel-liḃֽ⁠wò׃"],[7,3,"ט֥וֹב כַּ֖עַס מִ⁠שְּׂחֹ֑ק כִּֽי־בְ⁠רֹ֥עַ פָּנִ֖ים יִ֥יטַב לֵֽב׃","t֥wòb kȧ֖ʻas mi⁠şĕ̇̂ẖò֑q kiֽ̇y-bĕ⁠rò֥ʻa pá̇ni֖ym yi֥ytab léֽb׃"],[7,4,"לֵ֤ב חֲכָמִים֙ בְּ⁠בֵ֣ית אֵ֔בֶל וְ⁠לֵ֥ב כְּסִילִ֖ים בְּ⁠בֵ֥ית שִׂמְחָֽה׃","lé֤b ẖàkámiym֙ bĕ̇⁠bé֣yţ ʼé֔bel wĕ⁠lé֥b kĕ̇siyli֖ym bĕ̇⁠bé֥yţ şîmĕẖáֽh׃"],[7,5,"ט֕וֹב לִ⁠שְׁמֹ֖עַ גַּעֲרַ֣ת חָכָ֑ם מֵ⁠אִ֕ישׁ שֹׁמֵ֖עַ שִׁ֥יר כְּסִילִֽים׃","t֕wòb li⁠şĕ̌mò֖ʻa gȧʻàra֣ţ ẖáká֑m mé⁠ʼi֕yş̌ şò̌mé֖ʻa şǐ֥yr kĕ̇siyliֽym׃"],[7,6,"כִּ֣י כְ⁠ק֤וֹל הַ⁠סִּירִים֙ תַּ֣חַת הַ⁠סִּ֔יר כֵּ֖ן שְׂחֹ֣ק הַ⁠כְּסִ֑יל וְ⁠גַם־זֶ֖ה הָֽבֶל׃","ki֣̇y kĕ⁠q֤wòl ha⁠si̇yriym֙ ţȧ֣ẖaţ ha⁠si̇֔yr ké֖̇n şĕ̂ẖò֣q ha⁠kĕ̇si֑yl wĕ⁠gam-ze֖h háֽbel׃"],[7,7,"כִּ֥י הָ⁠עֹ֖שֶׁק יְהוֹלֵ֣ל חָכָ֑ם וִֽ⁠יאַבֵּ֥ד אֶת־לֵ֖ב מַתָּנָֽה׃","ki֥̇y há⁠ʻò֖şěq yĕhwòlé֣l ẖáká֑m wiֽ⁠yʼabé֥̇d ʼeţ-lé֖b maţá̇náֽh׃"],[7,8,"ט֛וֹב אַחֲרִ֥ית דָּבָ֖ר מֵֽ⁠רֵאשִׁית֑⁠וֹ ט֥וֹב אֶֽרֶךְ־ר֖וּחַ מִ⁠גְּבַהּ־רֽוּחַ׃","t֛wòb ʼaẖàri֥yţ dá̇bá֖r mֽé⁠réʼşǐyţ֑⁠wò t֥wòb ʼeֽrekĕ-r֖ẇẖa mi⁠gĕ̇baḣ-rֽẇẖa׃"],[7,9,"אַל־תְּבַהֵ֥ל בְּ⁠רֽוּחֲ⁠ךָ֖ לִ⁠כְע֑וֹס כִּ֣י כַ֔עַס בְּ⁠חֵ֥יק כְּסִילִ֖ים יָנֽוּחַ׃","ʼal-ţĕ̇bahé֥l bĕ̇⁠rֽẇẖà⁠ká֖ li⁠kĕʻ֑wòs ki֣̇y ka֔ʻas bĕ̇⁠ẖé֥yq kĕ̇siyli֖ym yánֽẇẖa׃"],[7,10,"אַל־תֹּאמַר֙ מֶ֣ה הָיָ֔ה שֶׁ֤⁠הַ⁠יָּמִים֙ הָ⁠רִ֣אשֹׁנִ֔ים הָי֥וּ טוֹבִ֖ים מֵ⁠אֵ֑לֶּה כִּ֛י לֹ֥א מֵ⁠חָכְמָ֖ה שָׁאַ֥לְתָּ עַל־זֶֽה׃","ʼal-ţò̇ʼmar֙ me֣h háyá֔h şě֤⁠ha⁠yá̇miym֙ há⁠ri֣ʼşò̌ni֔ym háy֥ẇ twòbi֖ym mé⁠ʼé֑lėh ki֛̇y lò֥ʼ mé⁠ẖákĕmá֖h şá̌ʼa֥lĕţá̇ ʻal-zeֽh׃"],[7,11,"טוֹבָ֥ה חָכְמָ֖ה עִֽם־נַחֲלָ֑ה וְ⁠יֹתֵ֖ר לְ⁠רֹאֵ֥י הַ⁠שָּֽׁמֶשׁ׃","twòbá֥h ẖákĕmá֖h ʻiֽm-naẖàlá֑h wĕ⁠yòţé֖r lĕ⁠ròʼé֥y ha⁠şáֽ̇̌meş̌׃"],[7,12,"כִּ֛י בְּ⁠צֵ֥ל הַֽ⁠חָכְמָ֖ה בְּ⁠צֵ֣ל הַ⁠כָּ֑סֶף וְ⁠יִתְר֣וֹן דַּ֔עַת הַֽ⁠חָכְמָ֖ה תְּחַיֶּ֥ה בְעָלֶֽי⁠הָ׃","ki֛̇y bĕ̇⁠ẕé֥l haֽ⁠ẖákĕmá֖h bĕ̇⁠ẕé֣l ha⁠ká֑̇sep wĕ⁠yiţĕr֣wòn dȧ֔ʻaţ haֽ⁠ẖákĕmá֖h ţĕ̇ẖayė֥h bĕʻáleֽy⁠há׃"],[7,13,"רְאֵ֖ה אֶת־מַעֲשֵׂ֣ה הָ⁠אֱלֹהִ֑ים כִּ֣י מִ֤י יוּכַל֙ לְ⁠תַקֵּ֔ן אֵ֖ת אֲשֶׁ֥ר עִוְּתֽ⁠וֹ׃","rĕʼé֖h ʼeţ-maʻàşé֣̂h há⁠ʼèlòhi֑ym ki֣̇y mi֤y yẇkal֙ lĕ⁠ţaqé̇֔n ʼé֖ţ ʼàşě֥r ʻiwĕ̇ţֽ⁠wò׃"],[7,14,"בְּ⁠י֤וֹם טוֹבָה֙ הֱיֵ֣ה בְ⁠ט֔וֹב וּ⁠בְ⁠י֥וֹם רָעָ֖ה רְאֵ֑ה גַּ֣ם אֶת־זֶ֤ה לְ⁠עֻמַּת־זֶה֙ עָשָׂ֣ה הָֽ⁠אֱלֹהִ֔ים עַל־דִּבְרַ֗ת שֶׁ⁠לֹּ֨א יִמְצָ֧א הָֽ⁠אָדָ֛ם אַחֲרָ֖י⁠ו מְאֽוּמָה׃","bĕ̇⁠y֤wòm twòbáh֙ hèyé֣h bĕ⁠t֔wòb ẇ⁠bĕ⁠y֥wòm ráʻá֖h rĕʼé֑h gȧ֣m ʼeţ-ze֤h lĕ⁠ʻumȧţ-zeh֙ ʻáşá֣̂h háֽ⁠ʼèlòhi֔ym ʻal-di̇bĕra֗ţ şě⁠lò̇֨ʼ yimĕẕá֧ʼ háֽ⁠ʼádá֛m ʼaẖàrá֖y⁠w mĕʼֽẇmáh׃"],[7,15,"אֶת־הַ⁠כֹּ֥ל רָאִ֖יתִי בִּ⁠ימֵ֣י הֶבְלִ֑⁠י יֵ֤שׁ צַדִּיק֙ אֹבֵ֣ד בְּ⁠צִדְק֔⁠וֹ וְ⁠יֵ֣שׁ רָשָׁ֔ע מַאֲרִ֖יךְ בְּ⁠רָעָתֽ⁠וֹ׃","ʼeţ-ha⁠kò֥̇l ráʼi֖yţiy bi̇⁠ymé֣y hebĕli֑⁠y yé֤ş̌ ẕadi̇yq֙ ʼòbé֣d bĕ̇⁠ẕidĕq֔⁠wò wĕ⁠yé֣ş̌ ráşá̌֔ʻ maʼàri֖ykĕ bĕ̇⁠ráʻáţֽ⁠wò׃"],[7,16,"אַל־תְּהִ֤י צַדִּיק֙ הַרְבֵּ֔ה וְ⁠אַל־תִּתְחַכַּ֖ם יוֹתֵ֑ר לָ֖⁠מָּה תִּשּׁוֹמֵֽם׃","ʼal-ţĕ̇hi֤y ẕadi̇yq֙ harĕbé̇֔h wĕ⁠ʼal-ţi̇ţĕẖakȧ֖m ywòţé֑r lá֖⁠má̇h ţi̇ş̇̌wòméֽm׃"],[7,17,"אַל־תִּרְשַׁ֥ע הַרְבֵּ֖ה וְ⁠אַל־תְּהִ֣י סָכָ֑ל לָ֥⁠מָּה תָמ֖וּת בְּ⁠לֹ֥א עִתֶּֽ⁠ךָ׃","ʼal-ţi̇rĕşǎ֥ʻ harĕbé֖̇h wĕ⁠ʼal-ţĕ̇hi֣y sáká֑l lá֥⁠má̇h ţám֖ẇţ bĕ̇⁠lò֥ʼ ʻiţėֽ⁠ká׃"],[7,18,"ט֚וֹב אֲשֶׁ֣ר תֶּאֱחֹ֣ז בָּ⁠זֶ֔ה וְ⁠גַם־מִ⁠זֶּ֖ה אַל־תַּנַּ֣ח אֶת־יָדֶ֑⁠ךָ כִּֽי־יְרֵ֥א אֱלֹהִ֖ים יֵצֵ֥א אֶת־כֻּלָּֽ⁠ם׃","t֚wòb ʼàşě֣r ţėʼèẖò֣z bá̇⁠ze֔h wĕ⁠gam-mi⁠zė֖h ʼal-ţȧnȧ֣ẖ ʼeţ-yáde֑⁠ká kiֽ̇y-yĕré֥ʼ ʼèlòhi֖ym yéẕé֥ʼ ʼeţ-ku̇láֽ̇⁠m׃"],[7,19,"הַֽ⁠חָכְמָ֖ה תָּעֹ֣ז לֶ⁠חָכָ֑ם מֵֽ⁠עֲשָׂרָה֙ שַׁלִּיטִ֔ים אֲשֶׁ֥ר הָי֖וּ בָּ⁠עִֽיר׃","haֽ⁠ẖákĕmá֖h ţá̇ʻò֣z le⁠ẖáká֑m méֽ⁠ʻàşá̂ráh֙ şǎli̇yti֔ym ʼàşě֥r háy֖ẇ bá̇⁠ʻiֽyr׃"],[7,20,"כִּ֣י אָדָ֔ם אֵ֥ין צַדִּ֖יק בָּ⁠אָ֑רֶץ אֲשֶׁ֥ר יַעֲשֶׂה־טּ֖וֹב וְ⁠לֹ֥א יֶחֱטָֽא׃","ki֣̇y ʼádá֔m ʼé֥yn ẕadi֖̇yq bá̇⁠ʼá֑reẕ ʼàşě֥r yaʻàşêh-ṫ֖wòb wĕ⁠lò֥ʼ yeẖètáֽʼ׃"],[7,21,"גַּ֤ם לְ⁠כָל־הַ⁠דְּבָרִים֙ אֲשֶׁ֣ר יְדַבֵּ֔רוּ אַל־תִּתֵּ֖ן לִבֶּ֑⁠ךָ אֲשֶׁ֥ר לֹֽא־תִשְׁמַ֥ע אֶֽת־עַבְדְּ⁠ךָ֖ מְקַלְלֶֽ⁠ךָ׃","gȧ֤m lĕ⁠kál-ha⁠dĕ̇báriym֙ ʼàşě֣r yĕdabé̇֔rẇ ʼal-ţi̇ţé֖̇n libė֑⁠ká ʼàşě֥r lòֽʼ-ţişĕ̌ma֥ʻ ʼeֽţ-ʻabĕdĕ̇⁠ká֖ mĕqalĕleֽ⁠ká׃"],[7,22,"כִּ֛י גַּם־פְּעָמִ֥ים רַבּ֖וֹת יָדַ֣ע לִבֶּ֑⁠ךָ אֲשֶׁ֥ר גַּם־את קִלַּ֥לְתָּ אֲחֵרִֽים׃","ki֛̇y gȧm-pĕ̇ʻámi֥ym raḃ֖wòţ yáda֣ʻ libė֑⁠ká ʼàşě֥r gȧm-ʼţ qilȧ֥lĕţá̇ ʼàẖériֽym׃"],[7,23,"כָּל־זֹ֖ה נִסִּ֣יתִי בַֽ⁠חָכְמָ֑ה אָמַ֣רְתִּי אֶחְכָּ֔מָה וְ⁠הִ֖יא רְחוֹקָ֥ה מִמֶּֽ⁠נִּי׃","ká̇l-zò֖h nisi֣̇yţiy baֽ⁠ẖákĕmá֑h ʼáma֣rĕţi̇y ʼeẖĕká̇֔máh wĕ⁠hi֖yʼ rĕẖwòqá֥h mimėֽ⁠ni̇y׃"],[7,24,"רָח֖וֹק מַה־שֶּׁ⁠הָיָ֑ה וְ⁠עָמֹ֥ק ׀ עָמֹ֖ק מִ֥י יִמְצָאֶֽ⁠נּוּ׃","ráẖ֖wòq mah-şė̌⁠háyá֑h wĕ⁠ʻámò֥q ׀ ʻámò֖q mi֥y yimĕẕáʼeֽ⁠ṅẇ׃"],[7,25,"סַבּ֨וֹתִֽי אֲנִ֤י וְ⁠לִבִּ⁠י֙ לָ⁠דַ֣עַת וְ⁠לָ⁠ת֔וּר וּ⁠בַקֵּ֥שׁ חָכְמָ֖ה וְ⁠חֶשְׁבּ֑וֹן וְ⁠לָ⁠דַ֨עַת֙ רֶ֣שַׁע כֶּ֔סֶל וְ⁠הַ⁠סִּכְל֖וּת הוֹלֵלֽוֹת׃","saḃ֨wòţiֽy ʼàni֤y wĕ⁠libi̇⁠y֙ lá⁠da֣ʻaţ wĕ⁠lá⁠ţ֔ẇr ẇ⁠baqé֥̇ş̌ ẖákĕmá֖h wĕ⁠ẖeşĕ̌ḃ֑wòn wĕ⁠lá⁠da֨ʻaţ֙ re֣şǎʻ kė֔sel wĕ⁠ha⁠si̇kĕl֖ẇţ hwòlélֽwòţ׃"],[7,26,"וּ⁠מוֹצֶ֨א אֲנִ֜י מַ֣ר מִ⁠מָּ֗וֶת אֶת־הָֽ⁠אִשָּׁה֙ אֲשֶׁר־הִ֨יא מְצוֹדִ֧ים וַ⁠חֲרָמִ֛ים לִבָּ֖⁠הּ אֲסוּרִ֣ים יָדֶ֑י⁠הָ ט֞וֹב לִ⁠פְנֵ֤י הָ⁠אֱלֹהִים֙ יִמָּלֵ֣ט מִמֶּ֔⁠נָּה וְ⁠חוֹטֵ֖א יִלָּ֥כֶד בָּֽ⁠הּ׃","ẇ⁠mwòẕe֨ʼ ʼàni֜y ma֣r mi⁠má̇֗weţ ʼeţ-háֽ⁠ʼişá̇̌h֙ ʼàşěr-hi֨yʼ mĕẕwòdi֧ym wa⁠ẖàrámi֛ym libá֖̇⁠ḣ ʼàsẇri֣ym yáde֑y⁠há t֞wòb li⁠pĕné֤y há⁠ʼèlòhiym֙ yimá̇lé֣t mimė֔⁠ná̇h wĕ⁠ẖwòté֖ʼ yilá֥̇ked báֽ̇⁠ḣ׃"],[7,27,"רְאֵה֙ זֶ֣ה מָצָ֔אתִי אָמְרָ֖ה קֹהֶ֑לֶת אַחַ֥ת לְ⁠אַחַ֖ת לִ⁠מְצֹ֥א חֶשְׁבּֽוֹן׃","rĕʼéh֙ ze֣h máẕá֔ʼţiy ʼámĕrá֖h qòhe֑leţ ʼaẖa֥ţ lĕ⁠ʼaẖa֖ţ li⁠mĕẕò֥ʼ ẖeşĕ̌ḃֽwòn׃"],[7,28,"אֲשֶׁ֛ר עוֹד־בִּקְשָׁ֥ה נַפְשִׁ֖⁠י וְ⁠לֹ֣א מָצָ֑אתִי אָדָ֞ם אֶחָ֤ד מֵ⁠אֶ֨לֶף֙ מָצָ֔אתִי וְ⁠אִשָּׁ֥ה בְ⁠כָל־אֵ֖לֶּה לֹ֥א מָצָֽאתִי׃","ʼàşě֛r ʻwòd-bi̇qĕşá֥̌h napĕşǐ֖⁠y wĕ⁠lò֣ʼ máẕá֑ʼţiy ʼádá֞m ʼeẖá֤d mé⁠ʼe֨lep֙ máẕá֔ʼţiy wĕ⁠ʼişá֥̇̌h bĕ⁠kál-ʼé֖lėh lò֥ʼ máẕáֽʼţiy׃"],[7,29,"לְ⁠בַד֙ רְאֵה־זֶ֣ה מָצָ֔אתִי אֲשֶׁ֨ר עָשָׂ֧ה הָ⁠אֱלֹהִ֛ים אֶת־הָ⁠אָדָ֖ם יָשָׁ֑ר וְ⁠הֵ֥מָּה בִקְשׁ֖וּ חִשְּׁבֹנ֥וֹת רַבִּֽים׃","lĕ⁠bad֙ rĕʼéh-ze֣h máẕá֔ʼţiy ʼàşě֨r ʻáşá֧̂h há⁠ʼèlòhi֛ym ʼeţ-há⁠ʼádá֖m yáşá֑̌r wĕ⁠hé֥má̇h biqĕş֖̌ẇ ẖişĕ̇̌bòn֥wòţ rabiֽ̇ym׃"],[8,1,"מִ֚י כְּ⁠הֶ֣⁠חָכָ֔ם וּ⁠מִ֥י יוֹדֵ֖עַ פֵּ֣שֶׁר דָּבָ֑ר חָכְמַ֤ת אָדָם֙ תָּאִ֣יר פָּנָ֔י⁠ו וְ⁠עֹ֥ז פָּנָ֖י⁠ו יְשֻׁנֶּֽא׃","mi֚y kĕ̇⁠he֣⁠ẖáká֔m ẇ⁠mi֥y ywòdé֖ʻa pé֣̇şěr dá̇bá֑r ẖákĕma֤ţ ʼádám֙ ţá̇ʼi֣yr pá̇ná֔y⁠w wĕ⁠ʻò֥z pá̇ná֖y⁠w yĕşǔnėֽʼ׃"],[8,2,"אֲנִי֙ פִּי־מֶ֣לֶךְ שְׁמ֔וֹר וְ⁠עַ֕ל דִּבְרַ֖ת שְׁבוּעַ֥ת אֱלֹהִֽים׃","ʼàniy֙ pi̇y-me֣lekĕ şĕ̌m֔wòr wĕ⁠ʻa֕l di̇bĕra֖ţ şĕ̌bẇʻa֥ţ ʼèlòhiֽym׃"],[8,3,"אַל־תִּבָּהֵ֤ל מִ⁠פָּנָי⁠ו֙ תֵּלֵ֔ךְ אַֽל־תַּעֲמֹ֖ד בְּ⁠דָבָ֣ר רָ֑ע כִּ֛י כָּל־אֲשֶׁ֥ר יַחְפֹּ֖ץ יַעֲשֶֽׂה׃","ʼal-ţi̇bá̇hé֤l mi⁠pá̇náy⁠w֙ ţé̇lé֔kĕ ʼaֽl-ţȧʻàmò֖d bĕ̇⁠dábá֣r rá֑ʻ ki֛̇y ká̇l-ʼàşě֥r yaẖĕpò֖̇ẕ yaʻàşêֽh׃"],[8,4,"בַּ⁠אֲשֶׁ֥ר דְּבַר־מֶ֖לֶךְ שִׁלְט֑וֹן וּ⁠מִ֥י יֹֽאמַר־ל֖⁠וֹ מַֽה־תַּעֲשֶֽׂה׃","bȧ⁠ʼàşě֥r dĕ̇bar-me֖lekĕ şǐlĕt֑wòn ẇ⁠mi֥y yòֽʼmar-l֖⁠wò maֽh-ţȧʻàşêֽh׃"],[8,5,"שׁוֹמֵ֣ר מִצְוָ֔ה לֹ֥א יֵדַ֖ע דָּבָ֣ר רָ֑ע וְ⁠עֵ֣ת וּ⁠מִשְׁפָּ֔ט יֵדַ֖ע לֵ֥ב חָכָֽם׃","ş̌wòmé֣r miẕĕwá֔h lò֥ʼ yéda֖ʻ dá̇bá֣r rá֑ʻ wĕ⁠ʻé֣ţ ẇ⁠mişĕ̌pá̇֔t yéda֖ʻ lé֥b ẖákáֽm׃"],[8,6,"כִּ֣י לְ⁠כָל־חֵ֔פֶץ יֵ֖שׁ עֵ֣ת וּ⁠מִשְׁפָּ֑ט כִּֽי־רָעַ֥ת הָ⁠אָדָ֖ם רַבָּ֥ה עָלָֽי⁠ו׃","ki֣̇y lĕ⁠kál-ẖé֔peẕ yé֖ş̌ ʻé֣ţ ẇ⁠mişĕ̌pá֑̇t kiֽ̇y-ráʻa֥ţ há⁠ʼádá֖m rabá֥̇h ʻáláֽy⁠w׃"],[8,7,"כִּֽי־אֵינֶ֥⁠נּוּ יֹדֵ֖עַ מַה־שֶּׁ⁠יִּֽהְיֶ֑ה כִּ֚י כַּ⁠אֲשֶׁ֣ר יִֽהְיֶ֔ה מִ֖י יַגִּ֥יד לֽ⁠וֹ׃","kiֽ̇y-ʼéyne֥⁠ṅẇ yòdé֖ʻa mah-şė̌⁠yiֽ̇hĕye֑h ki֚̇y kȧ⁠ʼàşě֣r yiֽhĕye֔h mi֖y yagi֥̇yd lֽ⁠wò׃"],[8,8,"אֵ֣ין אָדָ֞ם שַׁלִּ֤יט בָּ⁠ר֨וּחַ֙ לִ⁠כְל֣וֹא אֶת־הָ⁠ר֔וּחַ וְ⁠אֵ֤ין שִׁלְטוֹן֙ בְּ⁠י֣וֹם הַ⁠מָּ֔וֶת וְ⁠אֵ֥ין מִשְׁלַ֖חַת בַּ⁠מִּלְחָמָ֑ה וְ⁠לֹֽא־יְמַלֵּ֥ט רֶ֖שַׁע אֶת־בְּעָלָֽי⁠ו׃","ʼé֣yn ʼádá֞m şǎli֤̇yt bá̇⁠r֨ẇẖa֙ li⁠kĕl֣wòʼ ʼeţ-há⁠r֔ẇẖa wĕ⁠ʼé֤yn şǐlĕtwòn֙ bĕ̇⁠y֣wòm ha⁠má̇֔weţ wĕ⁠ʼé֥yn mişĕ̌la֖ẖaţ bȧ⁠mi̇lĕẖámá֑h wĕ⁠lòֽʼ-yĕmalé֥̇t re֖şǎʻ ʼeţ-bĕ̇ʻáláֽy⁠w׃"],[8,9,"אֶת־כָּל־זֶ֤ה רָאִ֨יתִי֙ וְ⁠נָת֣וֹן אֶת־לִבִּ֔⁠י לְ⁠כָֽל־מַעֲשֶׂ֔ה אֲשֶׁ֥ר נַעֲשָׂ֖ה תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ עֵ֗ת אֲשֶׁ֨ר שָׁלַ֧ט הָ⁠אָדָ֛ם בְּ⁠אָדָ֖ם לְ⁠רַ֥ע לֽ⁠וֹ׃","ʼeţ-ká̇l-ze֤h ráʼi֨yţiy֙ wĕ⁠náţ֣wòn ʼeţ-libi̇֔⁠y lĕ⁠káֽl-maʻàşê֔h ʼàşě֥r naʻàşá֖̂h ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ʻé֗ţ ʼàşě֨r şá̌la֧t há⁠ʼádá֛m bĕ̇⁠ʼádá֖m lĕ⁠ra֥ʻ lֽ⁠wò׃"],[8,10,"וּ⁠בְ⁠כֵ֡ן רָאִיתִי֩ רְשָׁעִ֨ים קְבֻרִ֜ים וָ⁠בָ֗אוּ וּ⁠מִ⁠מְּק֤וֹם קָדוֹשׁ֙ יְהַלֵּ֔כוּ וְ⁠יִֽשְׁתַּכְּח֥וּ בָ⁠עִ֖יר אֲשֶׁ֣ר כֵּן־עָשׂ֑וּ גַּם־זֶ֖ה הָֽבֶל׃","ẇ⁠bĕ⁠ké֡n ráʼiyţiy֩ rĕşá̌ʻi֨ym qĕburi֜ym wá⁠bá֗ʼẇ ẇ⁠mi⁠mĕ̇q֤wòm qádwòş̌֙ yĕhalé̇֔kẇ wĕ⁠yiֽşĕ̌ţȧkĕ̇ẖ֥ẇ bá⁠ʻi֖yr ʼàşě֣r ké̇n-ʻáş֑̂ẇ gȧm-ze֖h háֽbel׃"],[8,11,"אֲשֶׁר֙ אֵין־נַעֲשָׂ֣ה פִתְגָ֔ם מַעֲשֵׂ֥ה הָ⁠רָעָ֖ה מְהֵרָ֑ה עַל־כֵּ֡ן מָלֵ֞א לֵ֧ב בְּֽנֵי־הָ⁠אָדָ֛ם בָּ⁠הֶ֖ם לַ⁠עֲשׂ֥וֹת רָֽע׃","ʼàşěr֙ ʼéyn-naʻàşá֣̂h piţĕgá֔m maʻàşé֥̂h há⁠ráʻá֖h mĕhérá֑h ʻal-ké̇֡n málé֞ʼ lé֧b bĕֽ̇néy-há⁠ʼádá֛m bá̇⁠he֖m la⁠ʻàş֥̂wòţ ráֽʻ׃"],[8,12,"אֲשֶׁ֣ר חֹטֶ֗א עֹשֶׂ֥ה רָ֛ע מְאַ֖ת וּ⁠מַאֲרִ֣יךְ ל֑⁠וֹ כִּ֚י גַּם־יוֹדֵ֣עַ אָ֔נִי אֲשֶׁ֤ר יִהְיֶה־טּוֹב֙ לְ⁠יִרְאֵ֣י הָ⁠אֱלֹהִ֔ים אֲשֶׁ֥ר יִֽירְא֖וּ מִ⁠לְּ⁠פָנָֽי⁠ו׃","ʼàşě֣r ẖòte֗ʼ ʻòşê֥h rá֛ʻ mĕʼa֖ţ ẇ⁠maʼàri֣ykĕ l֑⁠wò ki֚̇y gȧm-ywòdé֣ʻa ʼá֔niy ʼàşě֤r yihĕyeh-ṫwòb֙ lĕ⁠yirĕʼé֣y há⁠ʼèlòhi֔ym ʼàşě֥r yiֽyrĕʼ֖ẇ mi⁠lĕ̇⁠pánáֽy⁠w׃"],[8,13,"וְ⁠טוֹב֙ לֹֽא־יִהְיֶ֣ה לָֽ⁠רָשָׁ֔ע וְ⁠לֹֽא־יַאֲרִ֥יךְ יָמִ֖ים כַּ⁠צֵּ֑ל אֲשֶׁ֛ר אֵינֶ֥⁠נּוּ יָרֵ֖א מִ⁠לִּ⁠פְנֵ֥י אֱלֹהִֽים׃","wĕ⁠twòb֙ lòֽʼ-yihĕye֣h láֽ⁠ráşá̌֔ʻ wĕ⁠lòֽʼ-yaʼàri֥ykĕ yámi֖ym kȧ⁠ẕé֑̇l ʼàşě֛r ʼéyne֥⁠ṅẇ yáré֖ʼ mi⁠li̇⁠pĕné֥y ʼèlòhiֽym׃"],[8,14,"יֶשׁ־הֶבֶל֮ אֲשֶׁ֣ר נַעֲשָׂ֣ה עַל־הָ⁠אָרֶץ֒ אֲשֶׁ֣ר ׀ יֵ֣שׁ צַדִּיקִ֗ים אֲשֶׁ֨ר מַגִּ֤יעַ אֲלֵ⁠הֶם֙ כְּ⁠מַעֲשֵׂ֣ה הָ⁠רְשָׁעִ֔ים וְ⁠יֵ֣שׁ רְשָׁעִ֔ים שֶׁ⁠מַּגִּ֥יעַ אֲלֵ⁠הֶ֖ם כְּ⁠מַעֲשֵׂ֣ה הַ⁠צַּדִּיקִ֑ים אָמַ֕רְתִּי שֶׁ⁠גַּם־זֶ֖ה הָֽבֶל׃","yeş̌-hebel֮ ʼàşě֣r naʻàşá֣̂h ʻal-há⁠ʼáreẕ֒ ʼàşě֣r ׀ yé֣ş̌ ẕadi̇yqi֗ym ʼàşě֨r magi֤̇yʻa ʼàlé⁠hem֙ kĕ̇⁠maʻàşé֣̂h há⁠rĕşá̌ʻi֔ym wĕ⁠yé֣ş̌ rĕşá̌ʻi֔ym şě⁠mȧgi֥̇yʻa ʼàlé⁠he֖m kĕ̇⁠maʻàşé֣̂h ha⁠ẕȧdi̇yqi֑ym ʼáma֕rĕţi̇y şě⁠gȧm-ze֖h háֽbel׃"],[8,15,"וְ⁠שִׁבַּ֤חְתִּֽי אֲנִי֙ אֶת־הַ⁠שִּׂמְחָ֔ה אֲשֶׁ֨ר אֵֽין־ט֤וֹב לָֽ⁠אָדָם֙ תַּ֣חַת הַ⁠שֶּׁ֔מֶשׁ כִּ֛י אִם־לֶ⁠אֱכ֥וֹל וְ⁠לִ⁠שְׁתּ֖וֹת וְ⁠לִ⁠שְׂמ֑וֹחַ וְ⁠ה֞וּא יִלְוֶ֣⁠נּוּ בַ⁠עֲמָל֗⁠וֹ יְמֵ֥י חַיָּ֛י⁠ו אֲשֶׁר־נָֽתַן־ל֥⁠וֹ הָ⁠אֱלֹהִ֖ים תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠şǐbȧ֤ẖĕţiֽ̇y ʼàniy֙ ʼeţ-ha⁠şi̇̂mĕẖá֔h ʼàşě֨r ʼéֽyn-t֤wòb láֽ⁠ʼádám֙ ţȧ֣ẖaţ ha⁠şė̌֔meş̌ ki֛̇y ʼim-le⁠ʼèk֥wòl wĕ⁠li⁠şĕ̌ţ֖̇wòţ wĕ⁠li⁠şĕ̂m֑wòẖa wĕ⁠h֞ẇʼ yilĕwe֣⁠ṅẇ ba⁠ʻàmál֗⁠wò yĕmé֥y ẖayá֛̇y⁠w ʼàşěr-náֽţan-l֥⁠wò há⁠ʼèlòhi֖ym ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[8,16,"כַּ⁠אֲשֶׁ֨ר נָתַ֤תִּי אֶת־לִבִּ⁠י֙ לָ⁠דַ֣עַת חָכְמָ֔ה וְ⁠לִ⁠רְאוֹת֙ אֶת־הָ֣⁠עִנְיָ֔ן אֲשֶׁ֥ר נַעֲשָׂ֖ה עַל־הָ⁠אָ֑רֶץ כִּ֣י גַ֤ם בַּ⁠יּוֹם֙ וּ⁠בַ⁠לַּ֔יְלָה שֵׁנָ֕ה בְּ⁠עֵינָ֖י⁠ו אֵינֶ֥⁠נּוּ רֹאֶֽה׃","kȧ⁠ʼàşě֨r náţa֤ţi̇y ʼeţ-libi̇⁠y֙ lá⁠da֣ʻaţ ẖákĕmá֔h wĕ⁠li⁠rĕʼwòţ֙ ʼeţ-há֣⁠ʻinĕyá֔n ʼàşě֥r naʻàşá֖̂h ʻal-há⁠ʼá֑reẕ ki֣̇y ga֤m bȧ⁠ẏwòm֙ ẇ⁠ba⁠lȧ֔yĕláh şé̌ná֕h bĕ̇⁠ʻéyná֖y⁠w ʼéyne֥⁠ṅẇ ròʼeֽh׃"],[8,17,"וְ⁠רָאִיתִי֮ אֶת־כָּל־מַעֲשֵׂ֣ה הָ⁠אֱלֹהִים֒ כִּי֩ לֹ֨א יוּכַ֜ל הָ⁠אָדָ֗ם לִ⁠מְצוֹא֙ אֶת־הַֽ⁠מַּעֲשֶׂה֙ אֲשֶׁ֣ר נַעֲשָׂ֣ה תַֽחַת־הַ⁠שֶּׁ֔מֶשׁ בְּ֠⁠שֶׁ⁠ל אֲשֶׁ֨ר יַעֲמֹ֧ל הָ⁠אָדָ֛ם לְ⁠בַקֵּ֖שׁ וְ⁠לֹ֣א יִמְצָ֑א וְ⁠גַ֨ם אִם־יֹאמַ֤ר הֶֽ⁠חָכָם֙ לָ⁠דַ֔עַת לֹ֥א יוּכַ֖ל לִ⁠מְצֹֽא׃","wĕ⁠ráʼiyţiy֮ ʼeţ-ká̇l-maʻàşé֣̂h há⁠ʼèlòhiym֒ ki̇y֩ lò֨ʼ yẇka֜l há⁠ʼádá֗m li⁠mĕẕwòʼ֙ ʼeţ-haֽ⁠mȧʻàşêh֙ ʼàşě֣r naʻàşá֣̂h ţaֽẖaţ-ha⁠şė̌֔meş̌ bĕ̇֠⁠şě⁠l ʼàşě֨r yaʻàmò֧l há⁠ʼádá֛m lĕ⁠baqé֖̇ş̌ wĕ⁠lò֣ʼ yimĕẕá֑ʼ wĕ⁠ga֨m ʼim-yòʼma֤r heֽ⁠ẖákám֙ lá⁠da֔ʻaţ lò֥ʼ yẇka֖l li⁠mĕẕòֽʼ׃"],[9,1,"כִּ֣י אֶת־כָּל־זֶ֞ה נָתַ֤תִּי אֶל־לִבִּ⁠י֙ וְ⁠לָ⁠ב֣וּר אֶת־כָּל־זֶ֔ה אֲשֶׁ֨ר הַ⁠צַּדִּיקִ֧ים וְ⁠הַ⁠חֲכָמִ֛ים וַ⁠עֲבָדֵי⁠הֶ֖ם בְּ⁠יַ֣ד הָ⁠אֱלֹהִ֑ים גַּֽם־אַהֲבָ֣ה גַם־שִׂנְאָ֗ה אֵ֤ין יוֹדֵ֨עַ֙ הָֽ⁠אָדָ֔ם הַ⁠כֹּ֖ל לִ⁠פְנֵי⁠הֶֽם׃","ki֣̇y ʼeţ-ká̇l-ze֞h náţa֤ţi̇y ʼel-libi̇⁠y֙ wĕ⁠lá⁠b֣ẇr ʼeţ-ká̇l-ze֔h ʼàşě֨r ha⁠ẕȧdi̇yqi֧ym wĕ⁠ha⁠ẖàkámi֛ym wa⁠ʻàbádéy⁠he֖m bĕ̇⁠ya֣d há⁠ʼèlòhi֑ym gȧֽm-ʼahàbá֣h gam-şînĕʼá֗h ʼé֤yn ywòdé֨ʻa֙ háֽ⁠ʼádá֔m ha⁠kò֖̇l li⁠pĕnéy⁠heֽm׃"],[9,2,"הַ⁠כֹּ֞ל כַּ⁠אֲשֶׁ֣ר לַ⁠כֹּ֗ל מִקְרֶ֨ה אֶחָ֜ד לַ⁠צַּדִּ֤יק וְ⁠לָ⁠רָשָׁע֙ לַ⁠טּוֹב֙ וְ⁠לַ⁠טָּה֣וֹר וְ⁠לַ⁠טָּמֵ֔א וְ⁠לַ⁠זֹּבֵ֔חַ וְ⁠לַ⁠אֲשֶׁ֖ר אֵינֶ֣⁠נּוּ זֹבֵ֑חַ כַּ⁠טּוֹב֙ כַּֽ⁠חֹטֶ֔א הַ⁠נִּשְׁבָּ֕ע כַּ⁠אֲשֶׁ֖ר שְׁבוּעָ֥ה יָרֵֽא׃","ha⁠kò̇֞l kȧ⁠ʼàşě֣r la⁠kò̇֗l miqĕre֨h ʼeẖá֜d la⁠ẕȧdi֤̇yq wĕ⁠lá⁠ráşá̌ʻ֙ la⁠ṫwòb֙ wĕ⁠la⁠tá̇h֣wòr wĕ⁠la⁠tá̇mé֔ʼ wĕ⁠la⁠zò̇bé֔ẖa wĕ⁠la⁠ʼàşě֖r ʼéyne֣⁠ṅẇ zòbé֑ẖa kȧ⁠ṫwòb֙ kȧֽ⁠ẖòte֔ʼ ha⁠ni̇şĕ̌bá̇֕ʻ kȧ⁠ʼàşě֖r şĕ̌bẇʻá֥h yáréֽʼ׃"],[9,3,"זֶ֣ה ׀ רָ֗ע בְּ⁠כֹ֤ל אֲשֶֽׁר־נַעֲשָׂה֙ תַּ֣חַת הַ⁠שֶּׁ֔מֶשׁ כִּֽי־מִקְרֶ֥ה אֶחָ֖ד לַ⁠כֹּ֑ל וְ⁠גַ֣ם לֵ֣ב בְּֽנֵי־הָ֠⁠אָדָם מָלֵא־רָ֨ע וְ⁠הוֹלֵל֤וֹת בִּ⁠לְבָבָ⁠ם֙ בְּ⁠חַיֵּי⁠הֶ֔ם וְ⁠אַחֲרָ֖י⁠ו אֶל־הַ⁠מֵּתִֽים׃","ze֣h ׀ rá֗ʻ bĕ̇⁠kò֤l ʼàşěֽr-naʻàşá̂h֙ ţȧ֣ẖaţ ha⁠şė̌֔meş̌ kiֽ̇y-miqĕre֥h ʼeẖá֖d la⁠kò֑̇l wĕ⁠ga֣m lé֣b bĕֽ̇néy-há֠⁠ʼádám máléʼ-rá֨ʻ wĕ⁠hwòlél֤wòţ bi̇⁠lĕbábá⁠m֙ bĕ̇⁠ẖayé̇y⁠he֔m wĕ⁠ʼaẖàrá֖y⁠w ʼel-ha⁠mé̇ţiֽym׃"],[9,4,"כִּי־מִי֙ אֲשֶׁ֣ר יבחר אֶ֥ל כָּל־הַ⁠חַיִּ֖ים יֵ֣שׁ בִּטָּח֑וֹן כִּֽי־לְ⁠כֶ֤לֶב חַי֙ ה֣וּא ט֔וֹב מִן־הָ⁠אַרְיֵ֖ה הַ⁠מֵּֽת׃","ki̇y-miy֙ ʼàşě֣r ybẖr ʼe֥l ká̇l-ha⁠ẖayi֖̇ym yé֣ş̌ bi̇tá̇ẖ֑wòn kiֽ̇y-lĕ⁠ke֤leb ẖay֙ h֣ẇʼ t֔wòb min-há⁠ʼarĕyé֖h ha⁠méֽ̇ţ׃"],[9,5,"כִּ֧י הַֽ⁠חַיִּ֛ים יוֹדְעִ֖ים שֶׁ⁠יָּמֻ֑תוּ וְ⁠הַ⁠מֵּתִ֞ים אֵינָ֧⁠ם יוֹדְעִ֣ים מְא֗וּמָה וְ⁠אֵֽין־ע֤וֹד לָ⁠הֶם֙ שָׂכָ֔ר כִּ֥י נִשְׁכַּ֖ח זִכְרָֽ⁠ם׃","ki֧̇y haֽ⁠ẖayi֛̇ym ywòdĕʻi֖ym şě⁠yá̇mu֑ţẇ wĕ⁠ha⁠mé̇ţi֞ym ʼéyná֧⁠m ywòdĕʻi֣ym mĕʼ֗ẇmáh wĕ⁠ʼéֽyn-ʻ֤wòd lá⁠hem֙ şá̂ká֔r ki֥̇y nişĕ̌kȧ֖ẖ zikĕráֽ⁠m׃"],[9,6,"גַּ֣ם אַהֲבָתָ֧⁠ם גַּם־שִׂנְאָתָ֛⁠ם גַּם־קִנְאָתָ֖⁠ם כְּבָ֣ר אָבָ֑דָה וְ⁠חֵ֨לֶק אֵין־לָ⁠הֶ֥ם עוֹד֙ לְ⁠עוֹלָ֔ם בְּ⁠כֹ֥ל אֲשֶֽׁר־נַעֲשָׂ֖ה תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","gȧ֣m ʼahàbáţá֧⁠m gȧm-şînĕʼáţá֛⁠m gȧm-qinĕʼáţá֖⁠m kĕ̇bá֣r ʼábá֑dáh wĕ⁠ẖé֨leq ʼéyn-lá⁠he֥m ʻwòd֙ lĕ⁠ʻwòlá֔m bĕ̇⁠kò֥l ʼàşěֽr-naʻàşá֖̂h ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[9,7,"לֵ֣ךְ אֱכֹ֤ל בְּ⁠שִׂמְחָה֙ לַחְמֶ֔⁠ךָ וּֽ⁠שֲׁתֵ֥ה בְ⁠לֶב־ט֖וֹב יֵינֶ֑⁠ךָ כִּ֣י כְבָ֔ר רָצָ֥ה הָ⁠אֱלֹהִ֖ים אֶֽת־מַעֲשֶֽׂי⁠ךָ׃","lé֣kĕ ʼèkò֤l bĕ̇⁠şîmĕẖáh֙ laẖĕme֔⁠ká ẇֽ⁠şà̌ţé֥h bĕ⁠leb-t֖wòb yéyne֑⁠ká ki֣̇y kĕbá֔r ráẕá֥h há⁠ʼèlòhi֖ym ʼeֽţ-maʻàşêֽy⁠ká׃"],[9,8,"בְּ⁠כָל־עֵ֕ת יִהְי֥וּ בְגָדֶ֖י⁠ךָ לְבָנִ֑ים וְ⁠שֶׁ֖מֶן עַל־רֹאשְׁ⁠ךָ֥ אַל־יֶחְסָֽר׃","bĕ̇⁠kál-ʻé֕ţ yihĕy֥ẇ bĕgáde֖y⁠ká lĕbáni֑ym wĕ⁠şě֖men ʻal-ròʼşĕ̌⁠ká֥ ʼal-yeẖĕsáֽr׃"],[9,9,"רְאֵ֨ה חַיִּ֜ים עִם־אִשָּׁ֣ה אֲשֶׁר־אָהַ֗בְתָּ כָּל־יְמֵי֙ חַיֵּ֣י הֶבְלֶ֔⁠ךָ אֲשֶׁ֤ר נָֽתַן־לְ⁠ךָ֙ תַּ֣חַת הַ⁠שֶּׁ֔מֶשׁ כֹּ֖ל יְמֵ֣י הֶבְלֶ֑⁠ךָ כִּ֣י ה֤וּא חֶלְקְ⁠ךָ֙ בַּֽ⁠חַיִּ֔ים וּ⁠בַ⁠עֲמָ֣לְ⁠ךָ֔ אֲשֶׁר־אַתָּ֥ה עָמֵ֖ל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","rĕʼé֨h ẖayi̇֜ym ʻim-ʼişá֣̇̌h ʼàşěr-ʼáha֗bĕţá̇ ká̇l-yĕméy֙ ẖayé֣̇y hebĕle֔⁠ká ʼàşě֤r náֽţan-lĕ⁠ká֙ ţȧ֣ẖaţ ha⁠şė̌֔meş̌ kò֖̇l yĕmé֣y hebĕle֑⁠ká ki֣̇y h֤ẇʼ ẖelĕqĕ⁠ká֙ bȧֽ⁠ẖayi̇֔ym ẇ⁠ba⁠ʻàmá֣lĕ⁠ká֔ ʼàşěr-ʼaţá֥̇h ʻámé֖l ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[9,10,"כֹּ֠ל אֲשֶׁ֨ר תִּמְצָ֧א יָֽדְ⁠ךָ֛ לַ⁠עֲשׂ֥וֹת בְּ⁠כֹחֲ⁠ךָ֖ עֲשֵׂ֑ה כִּי֩ אֵ֨ין מַעֲשֶׂ֤ה וְ⁠חֶשְׁבּוֹן֙ וְ⁠דַ֣עַת וְ⁠חָכְמָ֔ה בִּ⁠שְׁא֕וֹל אֲשֶׁ֥ר אַתָּ֖ה הֹלֵ֥ךְ שָֽׁמָּ⁠ה׃ס","kò̇֠l ʼàşě֨r ţi̇mĕẕá֧ʼ yáֽdĕ⁠ká֛ la⁠ʻàş֥̂wòţ bĕ̇⁠kòẖà⁠ká֖ ʻàşé֑̂h ki̇y֩ ʼé֨yn maʻàşê֤h wĕ⁠ẖeşĕ̌ḃwòn֙ wĕ⁠da֣ʻaţ wĕ⁠ẖákĕmá֔h bi̇⁠şĕ̌ʼ֕wòl ʼàşě֥r ʼaţá֖̇h hòlé֥kĕ şáֽ̌má̇⁠h׃s"],[9,11,"שַׁ֜בְתִּי וְ⁠רָאֹ֣ה תַֽחַת־הַ⁠שֶּׁ֗מֶשׁ כִּ֣י לֹא֩ לַ⁠קַּלִּ֨ים הַ⁠מֵּר֜וֹץ וְ⁠לֹ֧א לַ⁠גִּבּוֹרִ֣ים הַ⁠מִּלְחָמָ֗ה וְ֠⁠גַם לֹ֣א לַ⁠חֲכָמִ֥ים לֶ֨חֶם֙ וְ⁠גַ֨ם לֹ֤א לַ⁠נְּבֹנִים֙ עֹ֔שֶׁר וְ⁠גַ֛ם לֹ֥א לַ⁠יֹּדְעִ֖ים חֵ֑ן כִּי־עֵ֥ת וָ⁠פֶ֖גַע יִקְרֶ֥ה אֶת־כֻּלָּֽ⁠ם׃","şǎ֜bĕţi̇y wĕ⁠ráʼò֣h ţaֽẖaţ-ha⁠şė̌֗meş̌ ki֣̇y lòʼ֩ la⁠qȧli̇֨ym ha⁠mé̇r֜wòẕ wĕ⁠lò֧ʼ la⁠gi̇ḃwòri֣ym ha⁠mi̇lĕẖámá֗h wĕ֠⁠gam lò֣ʼ la⁠ẖàkámi֥ym le֨ẖem֙ wĕ⁠ga֨m lò֤ʼ la⁠nĕ̇bòniym֙ ʻò֔şěr wĕ⁠ga֛m lò֥ʼ la⁠yò̇dĕʻi֖ym ẖé֑n ki̇y-ʻé֥ţ wá⁠pe֖gaʻ yiqĕre֥h ʼeţ-ku̇láֽ̇⁠m׃"],[9,12,"כִּ֡י גַּם֩ לֹֽא־יֵדַ֨ע הָ⁠אָדָ֜ם אֶת־עִתּ֗⁠וֹ כַּ⁠דָּגִים֙ שֶׁ⁠נֶּֽאֱחָזִים֙ בִּ⁠מְצוֹדָ֣ה רָעָ֔ה וְ⁠כַ֨⁠צִּפֳּרִ֔ים הָ⁠אֲחֻז֖וֹת בַּ⁠פָּ֑ח כָּ⁠הֵ֗ם יֽוּקָשִׁים֙ בְּנֵ֣י הָֽ⁠אָדָ֔ם לְ⁠עֵ֣ת רָעָ֔ה כְּ⁠שֶׁ⁠תִּפּ֥וֹל עֲלֵי⁠הֶ֖ם פִּתְאֹֽם׃","ki̇֡y gȧm֩ lòֽʼ-yéda֨ʻ há⁠ʼádá֜m ʼeţ-ʻiţ̇֗⁠wò kȧ⁠dá̇giym֙ şě⁠nėֽʼèẖáziym֙ bi̇⁠mĕẕwòdá֣h ráʻá֔h wĕ⁠ka֨⁠ẕi̇pȯri֔ym há⁠ʼàẖuz֖wòţ bȧ⁠pá֑̇ẖ ká̇⁠hé֗m yֽẇqáşǐym֙ bĕ̇né֣y háֽ⁠ʼádá֔m lĕ⁠ʻé֣ţ ráʻá֔h kĕ̇⁠şě⁠ţi̇ṗ֥wòl ʻàléy⁠he֖m pi̇ţĕʼòֽm׃"],[9,13,"גַּם־זֹ֛ה רָאִ֥יתִי חָכְמָ֖ה תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וּ⁠גְדוֹלָ֥ה הִ֖יא אֵלָֽ⁠י׃","gȧm-zò֛h ráʼi֥yţiy ẖákĕmá֖h ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ẇ⁠gĕdwòlá֥h hi֖yʼ ʼéláֽ⁠y׃"],[9,14,"עִ֣יר קְטַנָּ֔ה וַ⁠אֲנָשִׁ֥ים בָּ֖⁠הּ מְעָ֑ט וּ⁠בָֽא־אֵלֶ֜י⁠הָ מֶ֤לֶךְ גָּדוֹל֙ וְ⁠סָבַ֣ב אֹתָ֔⁠הּ וּ⁠בָנָ֥ה עָלֶ֖י⁠הָ מְצוֹדִ֥ים גְּדֹלִֽים׃","ʻi֣yr qĕtaná̇֔h wa⁠ʼànáşǐ֥ym bá֖̇⁠ḣ mĕʻá֑t ẇ⁠báֽʼ-ʼéle֜y⁠há me֤lekĕ gá̇dwòl֙ wĕ⁠sába֣b ʼòţá֔⁠ḣ ẇ⁠báná֥h ʻále֖y⁠há mĕẕwòdi֥ym gĕ̇dòliֽym׃"],[9,15,"וּ⁠מָ֣צָא בָ֗⁠הּ אִ֤ישׁ מִסְכֵּן֙ חָכָ֔ם וּ⁠מִלַּט־ה֥וּא אֶת־הָ⁠עִ֖יר בְּ⁠חָכְמָת֑⁠וֹ וְ⁠אָדָם֙ לֹ֣א זָכַ֔ר אֶת־הָ⁠אִ֥ישׁ הַ⁠מִּסְכֵּ֖ן הַ⁠הּֽוּא׃","ẇ⁠má֣ẕáʼ bá֗⁠ḣ ʼi֤yş̌ misĕké̇n֙ ẖáká֔m ẇ⁠milȧt-h֥ẇʼ ʼeţ-há⁠ʻi֖yr bĕ̇⁠ẖákĕmáţ֑⁠wò wĕ⁠ʼádám֙ lò֣ʼ záka֔r ʼeţ-há⁠ʼi֥yş̌ ha⁠mi̇sĕké֖̇n ha⁠ḣֽẇʼ׃"],[9,16,"וְ⁠אָמַ֣רְתִּי אָ֔נִי טוֹבָ֥ה חָכְמָ֖ה מִ⁠גְּבוּרָ֑ה וְ⁠חָכְמַ֤ת הַ⁠מִּסְכֵּן֙ בְּזוּיָ֔ה וּ⁠דְבָרָ֖י⁠ו אֵינָ֥⁠ם נִשְׁמָעִֽים׃","wĕ⁠ʼáma֣rĕţi̇y ʼá֔niy twòbá֥h ẖákĕmá֖h mi⁠gĕ̇bẇrá֑h wĕ⁠ẖákĕma֤ţ ha⁠mi̇sĕké̇n֙ bĕ̇zẇyá֔h ẇ⁠dĕbárá֖y⁠w ʼéyná֥⁠m nişĕ̌máʻiֽym׃"],[9,17,"דִּבְרֵ֣י חֲכָמִ֔ים בְּ⁠נַ֖חַת נִשְׁמָעִ֑ים מִ⁠זַּעֲקַ֥ת מוֹשֵׁ֖ל בַּ⁠כְּסִילִֽים׃","di̇bĕré֣y ẖàkámi֔ym bĕ̇⁠na֖ẖaţ nişĕ̌máʻi֑ym mi⁠zȧʻàqa֥ţ mwòşé֖̌l bȧ⁠kĕ̇siyliֽym׃"],[9,18,"טוֹבָ֥ה חָכְמָ֖ה מִ⁠כְּלֵ֣י קְרָ֑ב וְ⁠חוֹטֶ֣א אֶחָ֔ד יְאַבֵּ֥ד טוֹבָ֥ה הַרְבֵּֽה׃","twòbá֥h ẖákĕmá֖h mi⁠kĕ̇lé֣y qĕrá֑b wĕ⁠ẖwòte֣ʼ ʼeẖá֔d yĕʼabé֥̇d twòbá֥h harĕbéֽ̇h׃"],[10,1,"זְב֣וּבֵי מָ֔וֶת יַבְאִ֥ישׁ יַבִּ֖יעַ שֶׁ֣מֶן רוֹקֵ֑חַ יָקָ֛ר מֵ⁠חָכְמָ֥ה מִ⁠כָּב֖וֹד סִכְל֥וּת מְעָֽט׃","zĕb֣ẇbéy má֔weţ yabĕʼi֥yş̌ yabi֖̇yʻa şě֣men rwòqé֑ẖa yáqá֛r mé⁠ẖákĕmá֥h mi⁠ká̇b֖wòd sikĕl֥ẇţ mĕʻáֽt׃"],[10,2,"לֵ֤ב חָכָם֙ לִֽ⁠ימִינ֔⁠וֹ וְ⁠לֵ֥ב כְּסִ֖יל לִ⁠שְׂמֹאלֽ⁠וֹ׃","lé֤b ẖákám֙ liֽ⁠ymiyn֔⁠wò wĕ⁠lé֥b kĕ̇si֖yl li⁠şĕ̂mòʼlֽ⁠wò׃"],[10,3,"וְ⁠גַם־בַּ⁠דֶּ֛רֶךְ כ⁠ש⁠ה⁠סכל הֹלֵ֖ךְ לִבּ֣⁠וֹ חָסֵ֑ר וְ⁠אָמַ֥ר לַ⁠כֹּ֖ל סָכָ֥ל הֽוּא׃","wĕ⁠gam-bȧ⁠dė֛rekĕ k⁠ş⁠h⁠skl hòlé֖kĕ liḃ֣⁠wò ẖásé֑r wĕ⁠ʼáma֥r la⁠kò֖̇l sáká֥l hֽẇʼ׃"],[10,4,"אִם־ר֤וּחַ הַ⁠מּוֹשֵׁל֙ תַּעֲלֶ֣ה עָלֶ֔י⁠ךָ מְקוֹמְ⁠ךָ֖ אַל־תַּנַּ֑ח כִּ֣י מַרְפֵּ֔א יַנִּ֖יחַ חֲטָאִ֥ים גְּדוֹלִֽים׃","ʼim-r֤ẇẖa ha⁠ṁwòşé̌l֙ ţȧʻàle֣h ʻále֔y⁠ká mĕqwòmĕ⁠ká֖ ʼal-ţȧnȧ֑ẖ ki֣̇y marĕpé̇֔ʼ yani֖̇yẖa ẖàtáʼi֥ym gĕ̇dwòliֽym׃"],[10,5,"יֵ֣שׁ רָעָ֔ה רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ כִּ⁠שְׁגָגָ֕ה שֶׁ⁠יֹּצָ֖א מִ⁠לִּ⁠פְנֵ֥י הַ⁠שַּׁלִּֽיט׃","yé֣ş̌ ráʻá֔h ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ki̇⁠şĕ̌gágá֕h şě⁠yò̇ẕá֖ʼ mi⁠li̇⁠pĕné֥y ha⁠şȧ̌liֽ̇yt׃"],[10,6,"נִתַּ֣ן הַ⁠סֶּ֔כֶל בַּ⁠מְּרוֹמִ֖ים רַבִּ֑ים וַ⁠עֲשִׁירִ֖ים בַּ⁠שֵּׁ֥פֶל יֵשֵֽׁבוּ׃","niţȧ֣n ha⁠sė֔kel bȧ⁠mĕ̇rwòmi֖ym rabi֑̇ym wa⁠ʻàşǐyri֖ym bȧ⁠şé֥̇̌pel yéşéֽ̌bẇ׃"],[10,7,"רָאִ֥יתִי עֲבָדִ֖ים עַל־סוּסִ֑ים וְ⁠שָׂרִ֛ים הֹלְכִ֥ים כַּ⁠עֲבָדִ֖ים עַל־הָ⁠אָֽרֶץ׃","ráʼi֥yţiy ʻàbádi֖ym ʻal-sẇsi֑ym wĕ⁠şá̂ri֛ym hòlĕki֥ym kȧ⁠ʻàbádi֖ym ʻal-há⁠ʼáֽreẕ׃"],[10,8,"חֹפֵ֥ר גּוּמָּ֖ץ בּ֣⁠וֹ יִפּ֑וֹל וּ⁠פֹרֵ֥ץ גָּדֵ֖ר יִשְּׁכֶ֥⁠נּוּ נָחָֽשׁ׃","ẖòpé֥r ġẇmá֖̇ẕ ḃ֣⁠wò yiṗ֑wòl ẇ⁠pòré֥ẕ gá̇dé֖r yişĕ̇̌ke֥⁠ṅẇ náẖáֽş̌׃"],[10,9,"מַסִּ֣יעַ אֲבָנִ֔ים יֵעָצֵ֖ב בָּ⁠הֶ֑ם בּוֹקֵ֥עַ עֵצִ֖ים יִסָּ֥כֶן בָּֽ⁠ם׃","masi֣̇yʻa ʼàbáni֔ym yéʻáẕé֖b bá̇⁠he֑m ḃwòqé֥ʻa ʻéẕi֖ym yisá֥̇ken báֽ̇⁠m׃"],[10,10,"אִם־קֵהָ֣ה הַ⁠בַּרְזֶ֗ל וְ⁠הוּא֙ לֹא־פָנִ֣ים קִלְקַ֔ל וַ⁠חֲיָלִ֖ים יְגַבֵּ֑ר וְ⁠יִתְר֥וֹן הכשיר חָכְמָֽה׃","ʼim-qéhá֣h ha⁠bȧrĕze֗l wĕ⁠hẇʼ֙ lòʼ-páni֣ym qilĕqa֔l wa⁠ẖàyáli֖ym yĕgabé֑̇r wĕ⁠yiţĕr֥wòn hkşyr ẖákĕmáֽh׃"],[10,11,"אִם־יִשֹּׁ֥ךְ הַ⁠נָּחָ֖שׁ בְּ⁠לוֹא־לָ֑חַשׁ וְ⁠אֵ֣ין יִתְר֔וֹן לְ⁠בַ֖עַל הַ⁠לָּשֽׁוֹן׃","ʼim-yişò֥̇̌kĕ ha⁠ná̇ẖá֖ş̌ bĕ̇⁠lwòʼ-lá֑ẖaş̌ wĕ⁠ʼé֣yn yiţĕr֔wòn lĕ⁠ba֖ʻal ha⁠lá̇şֽ̌wòn׃"],[10,12,"דִּבְרֵ֥י פִי־חָכָ֖ם חֵ֑ן וְ⁠שִׂפְת֥וֹת כְּסִ֖יל תְּבַלְּעֶֽ⁠נּוּ׃","di̇bĕré֥y piy-ẖáká֖m ẖé֑n wĕ⁠şîpĕţ֥wòţ kĕ̇si֖yl ţĕ̇balĕ̇ʻeֽ⁠ṅẇ׃"],[10,13,"תְּחִלַּ֥ת דִּבְרֵי־פִ֖י⁠הוּ סִכְל֑וּת וְ⁠אַחֲרִ֣ית פִּ֔י⁠הוּ הוֹלֵל֖וּת רָעָֽה׃","ţĕ̇ẖilȧ֥ţ di̇bĕréy-pi֖y⁠hẇ sikĕl֑ẇţ wĕ⁠ʼaẖàri֣yţ pi̇֔y⁠hẇ hwòlél֖ẇţ ráʻáֽh׃"],[10,14,"וְ⁠הַ⁠סָּכָ֖ל יַרְבֶּ֣ה דְבָרִ֑ים לֹא־יֵדַ֤ע הָ⁠אָדָם֙ מַה־שֶׁ⁠יִּֽהְיֶ֔ה וַ⁠אֲשֶׁ֤ר יִֽהְיֶה֙ מֵֽ⁠אַחֲרָ֔י⁠ו מִ֖י יַגִּ֥יד לֽ⁠וֹ׃","wĕ⁠ha⁠sá̇ká֖l yarĕbė֣h dĕbári֑ym lòʼ-yéda֤ʻ há⁠ʼádám֙ mah-şě⁠yiֽ̇hĕye֔h wa⁠ʼàşě֤r yiֽhĕyeh֙ méֽ⁠ʼaẖàrá֔y⁠w mi֖y yagi֥̇yd lֽ⁠wò׃"],[10,15,"עֲמַ֥ל הַ⁠כְּסִילִ֖ים תְּיַגְּעֶ֑⁠נּוּ אֲשֶׁ֥ר לֹֽא־יָדַ֖ע לָ⁠לֶ֥כֶת אֶל־עִֽיר׃","ʻàma֥l ha⁠kĕ̇siyli֖ym ţĕ̇yagĕ̇ʻe֑⁠ṅẇ ʼàşě֥r lòֽʼ-yáda֖ʻ lá⁠le֥keţ ʼel-ʻiֽyr׃"],[10,16,"אִֽי־לָ֣⁠ךְ אֶ֔רֶץ שֶׁ⁠מַּלְכֵּ֖⁠ךְ נָ֑עַר וְ⁠שָׂרַ֖יִ⁠ךְ בַּ⁠בֹּ֥קֶר יֹאכֵֽלוּ׃","ʼiֽy-lá֣⁠kĕ ʼe֔reẕ şě⁠mȧlĕké֖̇⁠kĕ ná֑ʻar wĕ⁠şá̂ra֖yi⁠kĕ bȧ⁠bò֥̇qer yòʼkéֽlẇ׃"],[10,17,"אַשְׁרֵ֣י⁠ךְ אֶ֔רֶץ שֶׁ⁠מַּלְכֵּ֖⁠ךְ בֶּן־חוֹרִ֑ים וְ⁠שָׂרַ֨יִ⁠ךְ֙ בָּ⁠עֵ֣ת יֹאכֵ֔לוּ בִּ⁠גְבוּרָ֖ה וְ⁠לֹ֥א בַ⁠שְּׁתִֽי׃","ʼaşĕ̌ré֣y⁠kĕ ʼe֔reẕ şě⁠mȧlĕké֖̇⁠kĕ bėn-ẖwòri֑ym wĕ⁠şá̂ra֨yi⁠kĕ֙ bá̇⁠ʻé֣ţ yòʼké֔lẇ bi̇⁠gĕbẇrá֖h wĕ⁠lò֥ʼ ba⁠şĕ̇̌ţiֽy׃"],[10,18,"בַּ⁠עֲצַלְתַּ֖יִם יִמַּ֣ךְ הַ⁠מְּקָרֶ֑ה וּ⁠בְ⁠שִׁפְל֥וּת יָדַ֖יִם יִדְלֹ֥ף הַ⁠בָּֽיִת׃","bȧ⁠ʻàẕalĕţȧ֖yim yimȧ֣kĕ ha⁠mĕ̇qáre֑h ẇ⁠bĕ⁠şǐpĕl֥ẇţ yáda֖yim yidĕlò֥p ha⁠báֽ̇yiţ׃"],[10,19,"לִ⁠שְׂחוֹק֙ עֹשִׂ֣ים לֶ֔חֶם וְ⁠יַ֖יִן יְשַׂמַּ֣ח חַיִּ֑ים וְ⁠הַ⁠כֶּ֖סֶף יַעֲנֶ֥ה אֶת־הַ⁠כֹּֽל׃","li⁠şĕ̂ẖwòq֙ ʻòşî֣ym le֔ẖem wĕ⁠ya֖yin yĕşâmȧ֣ẖ ẖayi֑̇ym wĕ⁠ha⁠kė֖sep yaʻàne֥h ʼeţ-ha⁠kòֽ̇l׃"],[10,20,"גַּ֣ם בְּ⁠מַדָּֽעֲ⁠ךָ֗ מֶ֚לֶךְ אַל־תְּקַלֵּ֔ל וּ⁠בְ⁠חַדְרֵי֙ מִשְׁכָּ֣בְ⁠ךָ֔ אַל־תְּקַלֵּ֖ל עָשִׁ֑יר כִּ֣י ע֤וֹף הַ⁠שָּׁמַ֨יִם֙ יוֹלִ֣יךְ אֶת־הַ⁠קּ֔וֹל וּ⁠בַ֥עַל ה⁠כנפים יַגֵּ֥יד דָּבָֽר׃","gȧ֣m bĕ̇⁠madáֽ̇ʻà⁠ká֗ me֚lekĕ ʼal-ţĕ̇qalé̇֔l ẇ⁠bĕ⁠ẖadĕréy֙ mişĕ̌ká֣̇bĕ⁠ká֔ ʼal-ţĕ̇qalé֖̇l ʻáşǐ֑yr ki֣̇y ʻ֤wòp ha⁠şá̇̌ma֨yim֙ ywòli֣ykĕ ʼeţ-ha⁠q̇֔wòl ẇ⁠ba֥ʻal h⁠knpym yagé֥̇yd dá̇báֽr׃"],[11,1,"שַׁלַּ֥ח לַחְמְ⁠ךָ֖ עַל־פְּנֵ֣י הַ⁠מָּ֑יִם כִּֽי־בְ⁠רֹ֥ב הַ⁠יָּמִ֖ים תִּמְצָאֶֽ⁠נּוּ׃","şǎlȧ֥ẖ laẖĕmĕ⁠ká֖ ʻal-pĕ̇né֣y ha⁠má֑̇yim kiֽ̇y-bĕ⁠rò֥b ha⁠yá̇mi֖ym ţi̇mĕẕáʼeֽ⁠ṅẇ׃"],[11,2,"תֶּן־חֵ֥לֶק לְ⁠שִׁבְעָ֖ה וְ⁠גַ֣ם לִ⁠שְׁמוֹנָ֑ה כִּ֚י לֹ֣א תֵדַ֔ע מַה־יִּהְיֶ֥ה רָעָ֖ה עַל־הָ⁠אָֽרֶץ׃","ţėn-ẖé֥leq lĕ⁠şǐbĕʻá֖h wĕ⁠ga֣m li⁠şĕ̌mwòná֑h ki֚̇y lò֣ʼ ţéda֔ʻ mah-yi̇hĕye֥h ráʻá֖h ʻal-há⁠ʼáֽreẕ׃"],[11,3,"אִם־יִמָּלְא֨וּ הֶ⁠עָבִ֥ים גֶּ֨שֶׁם֙ עַל־הָ⁠אָ֣רֶץ יָרִ֔יקוּ וְ⁠אִם־יִפּ֥וֹל עֵ֛ץ בַּ⁠דָּר֖וֹם וְ⁠אִ֣ם בַּ⁠צָּפ֑וֹן מְק֛וֹם שֶׁ⁠יִּפּ֥וֹל הָ⁠עֵ֖ץ שָׁ֥ם יְהֽוּא׃","ʼim-yimá̇lĕʼ֨ẇ he⁠ʻábi֥ym gė֨şěm֙ ʻal-há⁠ʼá֣reẕ yári֔yqẇ wĕ⁠ʼim-yiṗ֥wòl ʻé֛ẕ bȧ⁠dá̇r֖wòm wĕ⁠ʼi֣m bȧ⁠ẕá̇p֑wòn mĕq֛wòm şě⁠yi̇ṗ֥wòl há⁠ʻé֖ẕ şá֥̌m yĕhֽẇʼ׃"],[11,4,"שֹׁמֵ֥ר ר֖וּחַ לֹ֣א יִזְרָ֑ע וְ⁠רֹאֶ֥ה בֶ⁠עָבִ֖ים לֹ֥א יִקְצֽוֹר׃","şò̌mé֥r r֖ẇẖa lò֣ʼ yizĕrá֑ʻ wĕ⁠ròʼe֥h be⁠ʻábi֖ym lò֥ʼ yiqĕẕֽwòr׃"],[11,5,"כַּ⁠אֲשֶׁ֨ר אֵֽינְ⁠ךָ֤ יוֹדֵ֨עַ֙ מַה־דֶּ֣רֶךְ הָ⁠ר֔וּחַ כַּ⁠עֲצָמִ֖ים בְּ⁠בֶ֣טֶן הַ⁠מְּלֵאָ֑ה כָּ֗כָה לֹ֤א תֵדַע֙ אֶת־מַעֲשֵׂ֣ה הָֽ⁠אֱלֹהִ֔ים אֲשֶׁ֥ר יַעֲשֶׂ֖ה אֶת־הַ⁠כֹּֽל׃","kȧ⁠ʼàşě֨r ʼéֽynĕ⁠ká֤ ywòdé֨ʻa֙ mah-dė֣rekĕ há⁠r֔ẇẖa kȧ⁠ʻàẕámi֖ym bĕ̇⁠be֣ten ha⁠mĕ̇léʼá֑h ká̇֗káh lò֤ʼ ţédaʻ֙ ʼeţ-maʻàşé֣̂h háֽ⁠ʼèlòhi֔ym ʼàşě֥r yaʻàşê֖h ʼeţ-ha⁠kòֽ̇l׃"],[11,6,"בַּ⁠בֹּ֨קֶר֙ זְרַ֣ע אֶת־זַרְעֶ֔⁠ךָ וְ⁠לָ⁠עֶ֖רֶב אַל־תַּנַּ֣ח יָדֶ֑⁠ךָ כִּי֩ אֵֽינְ⁠ךָ֨ יוֹדֵ֜ע אֵ֣י זֶ֤ה יִכְשָׁר֙ הֲ⁠זֶ֣ה אוֹ־זֶ֔ה וְ⁠אִם־שְׁנֵי⁠הֶ֥ם כְּ⁠אֶחָ֖ד טוֹבִֽים׃","bȧ⁠bò̇֨qer֙ zĕra֣ʻ ʼeţ-zarĕʻe֔⁠ká wĕ⁠lá⁠ʻe֖reb ʼal-ţȧnȧ֣ẖ yáde֑⁠ká ki̇y֩ ʼéֽynĕ⁠ká֨ ywòdé֜ʻ ʼé֣y ze֤h yikĕşá̌r֙ hà⁠ze֣h ʼwò-ze֔h wĕ⁠ʼim-şĕ̌néy⁠he֥m kĕ̇⁠ʼeẖá֖d twòbiֽym׃"],[11,7,"וּ⁠מָת֖וֹק הָ⁠א֑וֹר וְ⁠ט֥וֹב לַֽ⁠עֵינַ֖יִם לִ⁠רְא֥וֹת אֶת־הַ⁠שָּֽׁמֶשׁ׃","ẇ⁠máţ֖wòq há⁠ʼ֑wòr wĕ⁠t֥wòb laֽ⁠ʻéyna֖yim li⁠rĕʼ֥wòţ ʼeţ-ha⁠şáֽ̇̌meş̌׃"],[11,8,"כִּ֣י אִם־שָׁנִ֥ים הַרְבֵּ֛ה יִחְיֶ֥ה הָ⁠אָדָ֖ם בְּ⁠כֻלָּ֣⁠ם יִשְׂמָ֑ח וְ⁠יִזְכֹּר֙ אֶת־יְמֵ֣י הַ⁠חֹ֔שֶׁךְ כִּֽי־הַרְבֵּ֥ה יִהְי֖וּ כָּל־שֶׁ⁠בָּ֥א הָֽבֶל׃","ki֣̇y ʼim-şá̌ni֥ym harĕbé֛̇h yiẖĕye֥h há⁠ʼádá֖m bĕ̇⁠kulá֣̇⁠m yişĕ̂má֑ẖ wĕ⁠yizĕkò̇r֙ ʼeţ-yĕmé֣y ha⁠ẖò֔şěkĕ kiֽ̇y-harĕbé֥̇h yihĕy֖ẇ ká̇l-şě⁠bá֥̇ʼ háֽbel׃"],[11,9,"שְׂמַ֧ח בָּח֣וּר בְּ⁠יַלְדוּתֶ֗י⁠ךָ וִֽ⁠יטִֽיבְ⁠ךָ֤ לִבְּ⁠ךָ֙ בִּ⁠ימֵ֣י בְחוּרוֹתֶ֔⁠ךָ וְ⁠הַלֵּךְ֙ בְּ⁠דַרְכֵ֣י לִבְּ⁠ךָ֔ וּ⁠בְ⁠מַרְאֵ֖י עֵינֶ֑י⁠ךָ וְ⁠דָ֕ע כִּ֧י עַל־כָּל־אֵ֛לֶּה יְבִֽיאֲ⁠ךָ֥ הָ⁠אֱלֹהִ֖ים בַּ⁠מִּשְׁפָּֽט׃","şĕ̂ma֧ẖ bá̇ẖ֣ẇr bĕ̇⁠yalĕdẇţe֗y⁠ká wiֽ⁠ytiֽybĕ⁠ká֤ libĕ̇⁠ká֙ bi̇⁠ymé֣y bĕẖẇrwòţe֔⁠ká wĕ⁠halé̇kĕ֙ bĕ̇⁠darĕké֣y libĕ̇⁠ká֔ ẇ⁠bĕ⁠marĕʼé֖y ʻéyne֑y⁠ká wĕ⁠dá֕ʻ ki֧̇y ʻal-ká̇l-ʼé֛lėh yĕbiֽyʼà⁠ká֥ há⁠ʼèlòhi֖ym bȧ⁠mi̇şĕ̌páֽ̇t׃"],[11,10,"וְ⁠הָסֵ֥ר כַּ֨עַס֙ מִ⁠לִּבֶּ֔⁠ךָ וְ⁠הַעֲבֵ֥ר רָעָ֖ה מִ⁠בְּשָׂרֶ֑⁠ךָ כִּֽי־הַ⁠יַּלְד֥וּת וְ⁠הַֽ⁠שַּׁחֲר֖וּת הָֽבֶל׃","wĕ⁠hásé֥r kȧ֨ʻas֙ mi⁠li̇bė֔⁠ká wĕ⁠haʻàbé֥r ráʻá֖h mi⁠bĕ̇şá̂re֑⁠ká kiֽ̇y-ha⁠yȧlĕd֥ẇţ wĕ⁠haֽ⁠şȧ̌ẖàr֖ẇţ háֽbel׃"],[12,1,"וּ⁠זְכֹר֙ אֶת־בּ֣וֹרְאֶ֔י⁠ךָ בִּ⁠ימֵ֖י בְּחוּרֹתֶ֑י⁠ךָ עַ֣ד אֲשֶׁ֤ר לֹא־יָבֹ֨אוּ֙ יְמֵ֣י הָֽ⁠רָעָ֔ה וְ⁠הִגִּ֣יעוּ שָׁנִ֔ים אֲשֶׁ֣ר תֹּאמַ֔ר אֵֽין־לִ֥⁠י בָ⁠הֶ֖ם חֵֽפֶץ׃","ẇ⁠zĕkòr֙ ʼeţ-ḃ֣wòrĕʼe֔y⁠ká bi̇⁠ymé֖y bĕ̇ẖẇròţe֑y⁠ká ʻa֣d ʼàşě֤r lòʼ-yábò֨ʼẇ֙ yĕmé֣y háֽ⁠ráʻá֔h wĕ⁠higi֣̇yʻẇ şá̌ni֔ym ʼàşě֣r ţò̇ʼma֔r ʼéֽyn-li֥⁠y bá⁠he֖m ẖéֽpeẕ׃"],[12,2,"עַ֠ד אֲשֶׁ֨ר לֹֽא־תֶחְשַׁ֤ךְ הַ⁠שֶּׁ֨מֶשׁ֙ וְ⁠הָ⁠א֔וֹר וְ⁠הַ⁠יָּרֵ֖חַ וְ⁠הַ⁠כּוֹכָבִ֑ים וְ⁠שָׁ֥בוּ הֶ⁠עָבִ֖ים אַחַ֥ר הַ⁠גָּֽשֶׁם׃","ʻa֠d ʼàşě֨r lòֽʼ-ţeẖĕşǎ֤kĕ ha⁠şė̌֨meş̌֙ wĕ⁠há⁠ʼ֔wòr wĕ⁠ha⁠yá̇ré֖ẖa wĕ⁠ha⁠k̇wòkábi֑ym wĕ⁠şá֥̌bẇ he⁠ʻábi֖ym ʼaẖa֥r ha⁠gáֽ̇şěm׃"],[12,3,"בַּ⁠יּ֗וֹם שֶׁ⁠יָּזֻ֨עוּ֙ שֹׁמְרֵ֣י הַ⁠בַּ֔יִת וְ⁠הִֽתְעַוְּת֖וּ אַנְשֵׁ֣י הֶ⁠חָ֑יִל וּ⁠בָטְל֤וּ הַ⁠טֹּֽחֲנוֹת֙ כִּ֣י מִעֵ֔טוּ וְ⁠חָשְׁכ֥וּ הָ⁠רֹא֖וֹת בָּ⁠אֲרֻבּֽוֹת׃","bȧ⁠ẏ֗wòm şě⁠yá̇zu֨ʻẇ֙ şò̌mĕré֣y ha⁠bȧ֔yiţ wĕ⁠hiֽţĕʻawĕ̇ţ֖ẇ ʼanĕşé֣̌y he⁠ẖá֑yil ẇ⁠bátĕl֤ẇ ha⁠tòֽ̇ẖànwòţ֙ ki֣̇y miʻé֔tẇ wĕ⁠ẖáşĕ̌k֥ẇ há⁠ròʼ֖wòţ bá̇⁠ʼàruḃֽwòţ׃"],[12,4,"וְ⁠סֻגְּר֤וּ דְלָתַ֨יִם֙ בַּ⁠שּׁ֔וּק בִּ⁠שְׁפַ֖ל ק֣וֹל הַֽ⁠טַּחֲנָ֑ה וְ⁠יָקוּם֙ לְ⁠ק֣וֹל הַ⁠צִּפּ֔וֹר וְ⁠יִשַּׁ֖חוּ כָּל־בְּנ֥וֹת הַ⁠שִּֽׁיר׃","wĕ⁠sugĕ̇r֤ẇ dĕláţa֨yim֙ bȧ⁠ş̇̌֔ẇq bi̇⁠şĕ̌pa֖l q֣wòl haֽ⁠tȧẖàná֑h wĕ⁠yáqẇm֙ lĕ⁠q֣wòl ha⁠ẕi̇ṗ֔wòr wĕ⁠yişȧ֖̌ẖẇ ká̇l-bĕ̇n֥wòţ ha⁠şiֽ̇̌yr׃"],[12,5,"גַּ֣ם מִ⁠גָּבֹ֤הַּ יִרָ֨אוּ֙ וְ⁠חַתְחַתִּ֣ים בַּ⁠דֶּ֔רֶךְ וְ⁠יָנֵ֤אץ הַ⁠שָּׁקֵד֙ וְ⁠יִסְתַּבֵּ֣ל הֶֽ⁠חָגָ֔ב וְ⁠תָפֵ֖ר הָֽ⁠אֲבִיּוֹנָ֑ה כִּֽי־הֹלֵ֤ךְ הָ⁠אָדָם֙ אֶל־בֵּ֣ית עוֹלָמ֔⁠וֹ וְ⁠סָבְב֥וּ בָ⁠שּׁ֖וּק הַ⁠סֹּפְדִֽים׃","gȧ֣m mi⁠gá̇bò֤hȧ yirá֨ʼẇ֙ wĕ⁠ẖaţĕẖaţi֣̇ym bȧ⁠dė֔rekĕ wĕ⁠yáné֤ʼẕ ha⁠şá̇̌qéd֙ wĕ⁠yisĕţȧbé֣̇l heֽ⁠ẖágá֔b wĕ⁠ţápé֖r háֽ⁠ʼàbiẏwòná֑h kiֽ̇y-hòlé֤kĕ há⁠ʼádám֙ ʼel-bé֣̇yţ ʻwòlám֔⁠wò wĕ⁠sábĕb֥ẇ bá⁠ş֖̇̌ẇq ha⁠sò̇pĕdiֽym׃"],[12,6,"עַ֣ד אֲשֶׁ֤ר לֹֽא־ירחק חֶ֣בֶל הַ⁠כֶּ֔סֶף וְ⁠תָרֻ֖ץ גֻּלַּ֣ת הַ⁠זָּהָ֑ב וְ⁠תִשָּׁ֤בֶר כַּד֙ עַל־הַ⁠מַּבּ֔וּעַ וְ⁠נָרֹ֥ץ הַ⁠גַּלְגַּ֖ל אֶל־הַ⁠בּֽוֹר׃","ʻa֣d ʼàşě֤r lòֽʼ-yrẖq ẖe֣bel ha⁠kė֔sep wĕ⁠ţáru֖ẕ gu̇lȧ֣ţ ha⁠zá̇há֑b wĕ⁠ţişá֤̇̌ber kȧd֙ ʻal-ha⁠mȧḃ֔ẇʻa wĕ⁠nárò֥ẕ ha⁠gȧlĕgȧ֖l ʼel-ha⁠ḃֽwòr׃"],[12,7,"וְ⁠יָשֹׁ֧ב הֶ⁠עָפָ֛ר עַל־הָ⁠אָ֖רֶץ כְּ⁠שֶׁ⁠הָיָ֑ה וְ⁠הָ⁠ר֣וּחַ תָּשׁ֔וּב אֶל־הָ⁠אֱלֹהִ֖ים אֲשֶׁ֥ר נְתָנָֽ⁠הּ׃","wĕ⁠yáşò֧̌b he⁠ʻápá֛r ʻal-há⁠ʼá֖reẕ kĕ̇⁠şě⁠háyá֑h wĕ⁠há⁠r֣ẇẖa ţá̇ş̌֔ẇb ʼel-há⁠ʼèlòhi֖ym ʼàşě֥r nĕţánáֽ⁠ḣ׃"],[12,8,"הֲבֵ֧ל הֲבָלִ֛ים אָמַ֥ר הַ⁠קּוֹהֶ֖לֶת הַ⁠כֹּ֥ל הָֽבֶל׃","hàbé֧l hàbáli֛ym ʼáma֥r ha⁠q̇wòhe֖leţ ha⁠kò֥̇l háֽbel׃"],[12,9,"וְ⁠יֹתֵ֕ר שֶׁ⁠הָיָ֥ה קֹהֶ֖לֶת חָכָ֑ם ע֗וֹד לִמַּד־דַּ֨עַת֙ אֶת־הָ⁠עָ֔ם וְ⁠אִזֵּ֣ן וְ⁠חִקֵּ֔ר תִּקֵּ֖ן מְשָׁלִ֥ים הַרְבֵּֽה׃","wĕ⁠yòţé֕r şě⁠háyá֥h qòhe֖leţ ẖáká֑m ʻ֗wòd limȧd-dȧ֨ʻaţ֙ ʼeţ-há⁠ʻá֔m wĕ⁠ʼizé֣̇n wĕ⁠ẖiqé̇֔r ţi̇qé֖̇n mĕşá̌li֥ym harĕbéֽ̇h׃"],[12,10,"בִּקֵּ֣שׁ קֹהֶ֔לֶת לִ⁠מְצֹ֖א דִּבְרֵי־חֵ֑פֶץ וְ⁠כָת֥וּב יֹ֖שֶׁר דִּבְרֵ֥י אֱמֶֽת׃","bi̇qé֣̇ş̌ qòhe֔leţ li⁠mĕẕò֖ʼ di̇bĕréy-ẖé֑peẕ wĕ⁠káţ֥ẇb yò֖şěr di̇bĕré֥y ʼèmeֽţ׃"],[12,11,"דִּבְרֵ֤י חֲכָמִים֙ כַּ⁠דָּ֣רְבֹנ֔וֹת וּֽ⁠כְ⁠מַשְׂמְר֥וֹת נְטוּעִ֖ים בַּעֲלֵ֣י אֲסֻפּ֑וֹת נִתְּנ֖וּ מֵ⁠רֹעֶ֥ה אֶחָֽד׃","di̇bĕré֤y ẖàkámiym֙ kȧ⁠dá֣̇rĕbòn֔wòţ ẇֽ⁠kĕ⁠maşĕ̂mĕr֥wòţ nĕtẇʻi֖ym bȧʻàlé֣y ʼàsuṗ֑wòţ niţĕ̇n֖ẇ mé⁠ròʻe֥h ʼeẖáֽd׃"],[12,12,"וְ⁠יֹתֵ֥ר מֵ⁠הֵ֖מָּה בְּנִ֣⁠י הִזָּהֵ֑ר עֲשׂ֨וֹת סְפָרִ֤ים הַרְבֵּה֙ אֵ֣ין קֵ֔ץ וְ⁠לַ֥הַג הַרְבֵּ֖ה יְגִעַ֥ת בָּשָֽׂר׃","wĕ⁠yòţé֥r mé⁠hé֖má̇h bĕ̇ni֣⁠y hizá̇hé֑r ʻàş̂֨wòţ sĕpári֤ym harĕbé̇h֙ ʼé֣yn qé֔ẕ wĕ⁠la֥hag harĕbé֖̇h yĕgiʻa֥ţ bá̇şáֽ̂r׃"],[12,13,"ס֥וֹף דָּבָ֖ר הַ⁠כֹּ֣ל נִשְׁמָ֑ע אֶת־הָ⁠אֱלֹהִ֤ים יְרָא֙ וְ⁠אֶת־מִצְוֺתָ֣י⁠ו שְׁמ֔וֹר כִּי־זֶ֖ה כָּל־הָ⁠אָדָֽם׃","s֥wòp dá̇bá֖r ha⁠kò֣̇l nişĕ̌má֑ʻ ʼeţ-há⁠ʼèlòhi֤ym yĕráʼ֙ wĕ⁠ʼeţ-miẕĕwֺţá֣y⁠w şĕ̌m֔wòr ki̇y-ze֖h ká̇l-há⁠ʼádáֽm׃"],[12,14,"כִּ֤י אֶת־כָּל־מַֽעֲשֶׂ֔ה הָ⁠אֱלֹהִ֛ים יָבִ֥א בְ⁠מִשְׁפָּ֖ט עַ֣ל כָּל־נֶעְלָ֑ם אִם־ט֖וֹב וְ⁠אִם־רָֽע׃","ki֤̇y ʼeţ-ká̇l-maֽʻàşê֔h há⁠ʼèlòhi֛ym yábi֥ʼ bĕ⁠mişĕ̌pá֖̇t ʻa֣l ká̇l-neʻĕlá֑m ʼim-t֖wòb wĕ⁠ʼim-ráֽʻ׃"]]}};